'use strict';
(()=>{const text={"无量纲": {"en": "Dimensionless", "fr": "Sans dimension", "es": "Adimensional", "eu": "Dimentsiorik gabe"}, "基因×菌株×培养×状态": {"en": "Gene × strain × culture × state", "fr": "Gène × souche × culture × état", "es": "Gen × cepa × cultivo × estado", "eu": "Genea × anduia × kultiboa × egoera"}, "基因对×菌株×培养×状态": {"en": "Gene pair × strain × culture × state", "fr": "Paire de gènes × souche × culture × état", "es": "Par de genes × cepa × cultivo × estado", "eu": "Gene-parea × anduia × kultiboa × egoera"}, "同一分析分组的合格细胞": {"en": "Eligible cells in the analysis group", "fr": "Cellules admissibles du groupe analysé", "es": "Células admisibles del grupo analizado", "eu": "Analisi-taldeko zelula hautagarriak"}, "以文库大小缩放时，估计量表示相对RNA丰度。": {"en": "Library-size scaling estimates relative RNA abundance.", "fr": "La normalisation par taille de bibliothèque estime l’abondance relative des ARN.", "es": "La escala por tamaño de biblioteca estima abundancia relativa de ARN.", "eu": "Liburutegi-tamainaren araberako eskalak RNA ugaritasun erlatiboa estimatzen du."}, "在菌株×培养×状态内估计；跨组区间按独立培养重抽样。": {"en": "Estimate within strain × culture × state; resample independent cultures for between-group intervals.", "fr": "Estimer par souche × culture × état ; rééchantillonner les cultures indépendantes pour les intervalles entre groupes.", "es": "Estimar por cepa × cultivo × estado; remuestrear cultivos independientes para intervalos entre grupos.", "eu": "Estimatu andui × kultibo × egoera barruan; kultibo independenteak berriz lagindu taldeen arteko tarteetarako."}, "研究方案": {"en": "Research plan", "fr": "Plan de recherche", "es": "Plan de investigación", "eu": "Ikerketa-plana"}, "检查拟合收敛、深度抽稀与留出培养预测。": {"en": "Check fit convergence, depth thinning and held-out culture prediction.", "fr": "Vérifier convergence, sous-échantillonnage en profondeur et prédiction sur cultures réservées.", "es": "Comprobar convergencia, submuestreo de profundidad y predicción en cultivos reservados.", "eu": "Egiaztatu doikuntzaren konbergentzia, sakonera-mehetzea eta gordetako kultiboen iragarpena."}, "潜在表达分布重建": {"en": "Latent expression-distribution reconstruction", "fr": "Reconstruction des distributions d’expression latentes", "es": "Reconstrucción de distribuciones latentes de expresión", "eu": "Adierazpen-banaketa latenteen berreraikuntza"}, "抽样噪音校正后，哪些基因仍具有宽分布、多峰或稳定的共波动？": {"en": "Which genes retain broad distributions, multiple modes or stable covariation after sampling correction?", "fr": "Quels gènes conservent des distributions larges, plusieurs modes ou une covariation stable après correction de l’échantillonnage ?", "es": "¿Qué genes conservan distribuciones amplias, varios modos o covariación estable tras corregir el muestreo?", "eu": "Zein genek mantentzen dituzte banaketa zabalak, modu anitzak edo kobariazio egonkorra laginketa zuzendu ondoren?"}, "用DESCEND估计非零比例、Gini与离散度；对重点基因及基因对用baredSC拟合潜在密度、模式权重与相关区间。": {"en": "Use DESCEND for nonzero fraction, Gini and dispersion; use baredSC to fit latent densities, mode weights and correlation intervals for selected genes and pairs.", "fr": "Estimer fraction non nulle, Gini et dispersion avec DESCEND ; ajuster densités latentes, poids des modes et intervalles de corrélation avec baredSC pour les candidats.", "es": "Estimar fracción no nula, Gini y dispersión con DESCEND; ajustar densidades latentes, pesos de modos e intervalos de correlación con baredSC para candidatos.", "eu": "Estimatu zatiki ez-nulua, Gini eta sakabanaketa DESCENDekin; hautagaien dentsitate latenteak, moduen pisuak eta korrelazio-tarteak doitu baredSCrekin."}, "原始UMI、逐细胞总UMI与协变量保持细胞顺序一致。": {"en": "Align raw UMIs, cell totals and covariates by cell identifier.", "fr": "Aligner UMI bruts, totaux cellulaires et covariables par identifiant cellulaire.", "es": "Alinear UMI originales, totales celulares y covariables por identificador celular.", "eu": "Lerrokatu UMI gordinak, zelula-totalak eta kobariableak zelula-identifikatzailearen arabera."}, "固定缩放方式、密度范围、混合成分候选与MCMC收敛规则。": {"en": "Fix scaling, density bounds, candidate mixture sizes and MCMC convergence criteria.", "fr": "Fixer l’échelle, les bornes de densité, les tailles des mélanges et les critères de convergence MCMC.", "es": "Fijar escala, límites de densidad, tamaños de mezcla y criterios de convergencia MCMC.", "eu": "Finkatu eskala, dentsitate-mugak, nahaste-tamainak eta MCMC konbergentzia-irizpideak."}, "潜在密度与不确定性": {"en": "Latent density and uncertainty", "fr": "Densité latente et incertitude", "es": "Densidad latente e incertidumbre", "eu": "Dentsitate latentea eta ziurgabetasuna"}, "非零比例、Gini与离散度": {"en": "Nonzero fraction, Gini and dispersion", "fr": "Fraction non nulle, Gini et dispersion", "es": "Fracción no nula, Gini y dispersión", "eu": "Zatiki ez-nulua, Gini eta sakabanaketa"}, "候选基因对的潜在相关": {"en": "Latent correlations of candidate gene pairs", "fr": "Corrélations latentes des paires candidates", "es": "Correlaciones latentes de pares candidatos", "eu": "Gene-pare hautagaien korrelazio latenteak"}, "推断对象是群体表达分布；混合成分数与细胞类型数分别解释。": {"en": "The target is a population expression distribution; mixture components and cell types are interpreted separately.", "fr": "La cible est une distribution d’expression de population ; composantes du mélange et types cellulaires ont des interprétations distinctes.", "es": "El objetivo es una distribución de expresión poblacional; los componentes de mezcla y tipos celulares se interpretan por separado.", "eu": "Helburua populazioaren adierazpen-banaketa da; nahaste-osagaiak eta zelula-motak bereiz interpretatzen dira."}, "重复基因与复合体的转录波动缓冲": {"en": "Transcript buffering in paralogs and complexes", "fr": "Tamponnement transcriptionnel des paralogues et complexes", "es": "Amortiguación transcripcional en parálogos y complejos", "eu": "Paralogoen eta konplexuen transkripzio-gorabeheren moteltzea"}, "重复基因的协变是否稳定其合计表达，哪些共享靶基因只改变噪音？": {"en": "Does paralog covariation stabilize summed expression, and which shared targets change noise alone?", "fr": "La covariation des paralogues stabilise-t-elle leur expression totale, et quelles cibles communes changent uniquement de bruit ?", "es": "¿La covariación de parálogos estabiliza su expresión conjunta y qué dianas compartidas cambian solo el ruido?", "eu": "Paralogoen kobariazioak adierazpen batura egonkortzen al du, eta zein helburu partekatuk aldatzen dute zarata soilik?"}, "按同源基因、复合体和共享靶基因集合，联合分析均值、校正协方差及合计RNA方差；与表达量、检出率和集合大小匹配的基因组比较。": {"en": "Analyze means, corrected covariance and summed RNA variance in paralog, complex and shared-target sets; compare with gene sets matched for abundance, detection and size.", "fr": "Analyser moyennes, covariance corrigée et variance de l’ARN total dans les ensembles de paralogues, complexes et cibles communes ; utiliser des ensembles appariés en abondance, détection et taille.", "es": "Analizar medias, covarianza corregida y varianza del ARN conjunto en parálogos, complejos y dianas compartidas; comparar conjuntos emparejados por abundancia, detección y tamaño.", "eu": "Aztertu batezbestekoak, kobariantza zuzendua eta RNA baturaren bariantza paralogo, konplexu eta helburu partekatuetan; alderatu ugaritasun, detekzio eta tamainaz parekatutako multzoekin."}, "固定重复基因、复合体及共享靶基因的来源版本；区分合计RNA与蛋白化学计量。": {"en": "Version paralog, complex and shared-target annotations; distinguish summed RNA from protein stoichiometry.", "fr": "Versionner les annotations de paralogues, complexes et cibles communes ; distinguer ARN total et stœchiométrie protéique.", "es": "Versionar anotaciones de parálogos, complejos y dianas compartidas; distinguir ARN conjunto y estequiometría proteica.", "eu": "Bertsionatu paralogoen, konplexuen eta helburu partekatuen anotazioak; bereizi RNA batura eta proteinen estekiometria."}, "先审核同源区域的多重比对和基因归属，再检验协变与合计方差。": {"en": "Audit multimapping and gene assignment in homologous regions before testing covariance and summed variance.", "fr": "Contrôler multi-alignements et attribution génique dans les régions homologues avant de tester covariance et variance totale.", "es": "Auditar multialineamiento y asignación génica en regiones homólogas antes de probar covarianza y varianza conjunta.", "eu": "Ikuskatu eskualde homologoetako lerrokatze anizkoitza eta gene-esleipena kobariantza eta baturaren bariantza probatu aurretik."}, "合计RNA稳定性图谱": {"en": "Summed RNA stability map", "fr": "Carte de stabilité de l’ARN total", "es": "Mapa de estabilidad del ARN conjunto", "eu": "RNA baturaren egonkortasun-mapa"}, "协方差对总方差的贡献": {"en": "Covariance contribution to total variance", "fr": "Contribution de la covariance à la variance totale", "es": "Contribución de covarianza a la varianza total", "eu": "Kobariantzaren ekarpena bariantza osoari"}, "共享靶基因的均值—噪音富集": {"en": "Mean–noise enrichment of shared targets", "fr": "Enrichissement moyenne–bruit des cibles communes", "es": "Enriquecimiento media–ruido de dianas compartidas", "eu": "Helburu partekatuen batezbesteko–zarata aberastea"}, "自然菌株比较定位转录缓冲候选；补偿机制结合已有扰动证据解释。": {"en": "Natural-strain comparisons identify transcript-buffering candidates; existing perturbation evidence informs compensation mechanisms.", "fr": "Les comparaisons de souches naturelles repèrent des candidats au tamponnement transcriptionnel ; les perturbations publiées éclairent les mécanismes compensatoires.", "es": "Las comparaciones de cepas naturales identifican candidatos de amortiguación transcripcional; la evidencia de perturbación informa mecanismos compensatorios.", "eu": "Andui naturalen konparazioek transkripzio-moteltzearen hautagaiak identifikatzen dituzte; perturbazio-ebidentziak konpentsazio-mekanismoak argitzen ditu."}, "RNA相对分配与比例稳定性": {"en": "Relative RNA allocation and proportionality", "fr": "Allocation relative des ARN et proportionnalité", "es": "Asignación relativa de ARN y proporcionalidad", "eu": "RNAren esleipen erlatiboa eta proportzionaltasuna"}, "基因间比例是否比单基因丰度更稳定，归一化参考如何改变噪音结论？": {"en": "Are gene ratios more stable than individual abundances, and how does the normalization reference affect noise conclusions?", "fr": "Les rapports géniques sont-ils plus stables que les abondances individuelles, et quel est l’effet de la référence de normalisation ?", "es": "¿Son las proporciones génicas más estables que las abundancias individuales y cómo afecta la referencia de normalización?", "eu": "Geneen ratioak ugaritasun indibidualak baino egonkorragoak al dira, eta nola eragiten du normalizazio-erreferentziak?"}, "用propr估计对数比方差和比例性；按培养比较效应，并改变参考基因集、零值处理及测序深度，检验RNA分配关系。": {"en": "Use propr to estimate log-ratio variance and proportionality; compare culture-level effects across reference sets, zero handling and sequencing depths.", "fr": "Estimer variance des log-rapports et proportionnalité avec propr ; comparer les effets par culture selon les références, le traitement des zéros et la profondeur.", "es": "Estimar varianza de log-cocientes y proporcionalidad con propr; comparar efectos por cultivo entre referencias, tratamiento de ceros y profundidades.", "eu": "Estimatu log-ratioen bariantza eta proportzionaltasuna propr-ekin; alderatu kultiboko efektuak erreferentzien, zeroen tratamenduaren eta sakoneren artean."}, "固定对数变换、参照集合、零值处理和基因对筛选；输出每项设置的结果。": {"en": "Fix log transformation, reference sets, zero handling and pair selection; retain results for each setting.", "fr": "Fixer transformation logarithmique, références, traitement des zéros et sélection des paires ; conserver chaque résultat.", "es": "Fijar transformación logarítmica, referencias, ceros y selección de pares; conservar resultados por configuración.", "eu": "Finkatu log-eraldaketa, erreferentziak, zeroen tratamendua eta pareen hautaketa; gorde konfigurazio bakoitzeko emaitzak."}, "使用培养层重抽样；对稀疏单细胞计数单独校准零值敏感性。": {"en": "Resample cultures; calibrate zero sensitivity specifically for sparse single-cell counts.", "fr": "Rééchantillonner les cultures ; calibrer la sensibilité aux zéros pour les comptages unicellulaires creux.", "es": "Remuestrear cultivos; calibrar sensibilidad a ceros para recuentos unicelulares dispersos.", "eu": "Kultiboak berriz lagindu; kalibratu zeroekiko sentikortasuna zelula bakarreko kontaketa sakabanatuetan."}, "稳定比例与失衡基因对": {"en": "Stable and imbalanced gene ratios", "fr": "Rapports géniques stables et déséquilibrés", "es": "Proporciones génicas estables y desequilibradas", "eu": "Gene-ratio egonkorrak eta desorekatuak"}, "参考与零值敏感性": {"en": "Reference and zero sensitivity", "fr": "Sensibilité à la référence et aux zéros", "es": "Sensibilidad a referencia y ceros", "eu": "Erreferentziarekiko eta zeroekiko sentikortasuna"}, "潜在非零表达比例": {"en": "Latent nonzero-expression fraction", "fr": "Fraction latente d’expression non nulle", "es": "Fracción latente de expresión no nula", "eu": "Adierazpen ez-nuluaren zatiki latentea"}, "用计数观测模型估计表达为正的细胞比例，并报告估计标准差。": {"en": "Estimate the fraction of cells with positive latent expression under a count observation model, with its standard error.", "fr": "Estimer la fraction de cellules à expression latente positive sous un modèle de comptage, avec son erreur standard.", "es": "Estimar la fracción celular con expresión latente positiva bajo un modelo de recuentos, con su error estándar.", "eu": "Estimatu adierazpen latente positiboko zelulen zatikia kontaketa-eredu baten bidez, bere errore estandarrarekin."}, "潜在表达Gini与变异系数": {"en": "Latent-expression Gini and coefficient of variation", "fr": "Gini et coefficient de variation de l’expression latente", "es": "Gini y coeficiente de variación de expresión latente", "eu": "Adierazpen latentearen Gini eta aldakuntza-koefizientea"}, "从DESCEND分布估计读取Gini与CV，保留不确定性和缩放定义。": {"en": "Extract Gini and CV from DESCEND distribution estimates, retaining uncertainty and the scaling definition.", "fr": "Extraire Gini et CV des distributions DESCEND, en conservant incertitude et définition de l’échelle.", "es": "Extraer Gini y CV de las distribuciones DESCEND, conservando incertidumbre y definición de escala.", "eu": "Atera Gini eta CV DESCEND banaketetatik, ziurgabetasuna eta eskalaren definizioa gordez."}, "潜在密度与模式支持": {"en": "Latent density and mode support", "fr": "Densité latente et support des modes", "es": "Densidad latente y soporte de modos", "eu": "Dentsitate latentea eta moduen euskarria"}, "联合查看密度区间、混合模型证据、有效样本量及不同随机种子的结果。": {"en": "Jointly assess density intervals, mixture-model evidence, effective sample size and results across random seeds.", "fr": "Évaluer conjointement intervalles de densité, évidence des mélanges, taille effective et résultats entre graines aléatoires.", "es": "Evaluar intervalos de densidad, evidencia de mezclas, tamaño efectivo y resultados entre semillas.", "eu": "Ebaluatu batera dentsitate-tarteak, nahaste-ereduen ebidentzia, lagin-tamaina eraginkorra eta hazi desberdinen emaitzak."}, "潜在基因对相关区间": {"en": "Latent gene-pair correlation interval", "fr": "Intervalle de corrélation latente entre gènes", "es": "Intervalo de correlación latente entre genes", "eu": "Gene-pareen korrelazio latentearen tartea"}, "拟合两个基因的联合潜在密度，保存相关后验、区间及培养间方向一致性。": {"en": "Fit the joint latent density of two genes; retain the correlation posterior, interval and direction across cultures.", "fr": "Ajuster la densité latente jointe de deux gènes ; conserver la corrélation postérieure, son intervalle et son sens entre cultures.", "es": "Ajustar la densidad latente conjunta de dos genes; conservar correlación posterior, intervalo y dirección entre cultivos.", "eu": "Doitu bi generen dentsitate latente bateratua; gorde korrelazioaren posteriorra, tartea eta kultiboen arteko norabidea."}, "重复基因合计RNA方差": {"en": "Variance of summed paralog RNA", "fr": "Variance de l’ARN cumulé des paralogues", "es": "Varianza del ARN conjunto de parálogos", "eu": "Paralogoen RNA baturaren bariantza"}, "在同一分子尺度上估计基因集合的均值与协方差，计算Var(sum X)=sum Var(X)+2sum Cov(Xg,Xh)。": {"en": "Estimate set means and covariance on one molecular scale; calculate Var(sum X)=sum Var(X)+2sum Cov(Xg,Xh).", "fr": "Estimer moyennes et covariance sur une même échelle moléculaire ; calculer Var(sum X)=sum Var(X)+2sum Cov(Xg,Xh).", "es": "Estimar medias y covarianza en una escala molecular común; calcular Var(sum X)=sum Var(X)+2sum Cov(Xg,Xh).", "eu": "Estimatu batezbestekoak eta kobariantza eskala molekular berean; kalkulatu Var(sum X)=sum Var(X)+2sum Cov(Xg,Xh)."}, "协方差对合计波动的贡献": {"en": "Covariance contribution to summed fluctuations", "fr": "Contribution de la covariance aux fluctuations cumulées", "es": "Contribución de covarianza a fluctuaciones conjuntas", "eu": "Kobariantzaren ekarpena gorabehera batuetan"}, "比较含协方差的合计方差与协方差置零的代数基线，并用表达量和检出率匹配的集合校准。": {"en": "Compare summed variance with a zero-covariance algebraic baseline; calibrate with abundance- and detection-matched sets.", "fr": "Comparer la variance totale à une base algébrique sans covariance ; calibrer avec des ensembles appariés en abondance et détection.", "es": "Comparar varianza conjunta con una base algebraica sin covarianza; calibrar con conjuntos emparejados por abundancia y detección.", "eu": "Alderatu baturaren bariantza kobariantzarik gabeko oinarri algebraikoarekin; kalibratu ugaritasunez eta detekzioz parekatutako multzoekin."}, "基因对数比方差与比例性": {"en": "Gene log-ratio variance and proportionality", "fr": "Variance des log-rapports géniques et proportionnalité", "es": "Varianza de log-cocientes génicos y proporcionalidad", "eu": "Geneen log-ratioen bariantza eta proportzionaltasuna"}, "计算基因对的对数比方差及rho比例性，保留零值处理、参照和逐培养估计。": {"en": "Compute gene-pair log-ratio variance and rho proportionality, retaining zero handling, reference and culture-specific estimates.", "fr": "Calculer variance des log-rapports et proportionnalité rho, avec traitement des zéros, référence et estimations par culture.", "es": "Calcular varianza de log-cocientes y proporcionalidad rho, conservando ceros, referencia y estimaciones por cultivo.", "eu": "Kalkulatu gene-pareen log-ratioen bariantza eta rho proportzionaltasuna, zeroen tratamendua, erreferentzia eta kultiboko estimazioak gordez."}, "RNA比例关系的设置敏感性": {"en": "Sensitivity of RNA proportionality to analysis settings", "fr": "Sensibilité de la proportionnalité ARN aux réglages", "es": "Sensibilidad de proporcionalidad de ARN a la configuración", "eu": "RNA proportzionaltasunaren sentikortasuna ezarpenekiko"}, "跨参照集合、零值处理与深度抽稀比较比例关系的方向、排序和培养层区间。": {"en": "Compare direction, ranking and culture-level intervals across reference sets, zero handling and depth thinning.", "fr": "Comparer sens, classement et intervalles par culture selon références, traitement des zéros et sous-échantillonnage.", "es": "Comparar dirección, rango e intervalos por cultivo entre referencias, ceros y submuestreo de profundidad.", "eu": "Alderatu norabidea, sailkapena eta kultibo-mailako tarteak erreferentzien, zeroen tratamenduaren eta sakonera-mehetzearen artean."}, "声明表达尺度的平方": {"en": "Squared declared expression scale", "fr": "Carré de l’échelle d’expression déclarée", "es": "Cuadrado de la escala de expresión declarada", "eu": "Adierazitako adierazpen-eskalaren karratua"}, "原始整数UMI计数": {"en": "Raw integer UMI counts", "fr": "Comptages UMI entiers bruts", "es": "Recuentos UMI enteros originales", "eu": "UMI zenbaketa oso gordinak"}, "逐细胞缩放因子及协变量": {"en": "Cell-specific scaling factors and covariates", "fr": "Facteurs d’échelle et covariables par cellule", "es": "Factores de escala y covariables por célula", "eu": "Zelulako eskala-faktoreak eta kobariableak"}, "按细胞ID与矩阵列对齐；Windows并行使用PSOCK。": {"en": "Align with matrix columns by cell ID; use PSOCK for parallel execution on Windows.", "fr": "Aligner avec les colonnes par identifiant ; utiliser PSOCK pour le parallélisme sous Windows.", "es": "Alinear con columnas por ID celular; usar PSOCK para ejecución paralela en Windows.", "eu": "Lerrokatu matrize-zutabeekin zelula-IDaren arabera; erabili PSOCK Windows-en paraleloan exekutatzeko."}, "逐细胞基因计数与nCount_RNA总UMI列": {"en": "Per-cell gene counts and the nCount_RNA total-UMI column", "fr": "Comptages géniques par cellule et colonne nCount_RNA des UMI totaux", "es": "Recuentos génicos por célula y columna nCount_RNA de UMI totales", "eu": "Zelulako gene-kontaketak eta UMI guztien nCount_RNA zutabea"}, "表达范围、混合成分、随机种子与MCMC采样": {"en": "Expression bounds, mixture size, random seed and MCMC sampling", "fr": "Bornes d’expression, taille du mélange, graine et échantillonnage MCMC", "es": "Límites de expresión, tamaño de mezcla, semilla y muestreo MCMC", "eu": "Adierazpen-mugak, nahaste-tamaina, hazia eta MCMC laginketa"}, "候选设置由密度覆盖、模型证据与收敛诊断决定。": {"en": "Select candidate settings using density coverage, model evidence and convergence diagnostics.", "fr": "Choisir les réglages selon couverture de densité, évidence et diagnostic de convergence.", "es": "Elegir configuración según cobertura de densidad, evidencia y convergencia.", "eu": "Hautatu ezarpenak dentsitate-estalduraren, eredu-ebidentziaren eta konbergentziaren arabera."}, "比例性统计、参考与零值处理": {"en": "Proportionality statistic, reference and zero handling", "fr": "Statistique de proportionnalité, référence et traitement des zéros", "es": "Estadístico de proporcionalidad, referencia y tratamiento de ceros", "eu": "Proportzionaltasun-estatistika, erreferentzia eta zeroen tratamendua"}, "记录metric、ivar、alpha；稀疏计数比较不同零值策略。": {"en": "Record metric, ivar and alpha; compare zero strategies for sparse counts.", "fr": "Consigner metric, ivar et alpha ; comparer les stratégies de zéros sur les comptages creux.", "es": "Registrar metric, ivar y alpha; comparar estrategias de ceros para recuentos dispersos.", "eu": "Erregistratu metric, ivar eta alpha; alderatu zero-estrategiak kontaketa sakabanatuetan."}, "分子抽样校正后的表达分布统计": {"en": "Expression-distribution statistics after sampling correction", "fr": "Statistiques de distribution après correction de l’échantillonnage", "es": "Estadísticos de distribución tras corregir muestreo", "eu": "Adierazpen-banaketaren estatistikak laginketa zuzendu ondoren"}, "以文库大小缩放时估计相对表达；拟合失败或过稀疏基因保留为缺失。": {"en": "Library-size scaling estimates relative expression; retain failed or overly sparse fits as missing.", "fr": "La taille de bibliothèque donne une expression relative ; conserver les ajustements échoués ou trop creux comme manquants.", "es": "El tamaño de biblioteca da expresión relativa; conservar ajustes fallidos o muy dispersos como ausentes.", "eu": "Liburutegi-tamainak adierazpen erlatiboa ematen du; huts egindako edo oso sakabanatutako doikuntzak falta gisa gorde."}, "候选基因的单变量及双变量潜在密度": {"en": "Univariate and bivariate latent densities for candidate genes", "fr": "Densités latentes univariées et bivariées des gènes candidats", "es": "Densidades latentes univariadas y bivariadas de genes candidatos", "eu": "Gene hautagaien dentsitate latente aldagai bakarrekoak eta bikoak"}, "针对少数候选基因精细拟合；每细胞总UMI参与观测模型，保留零计数。": {"en": "Fit selected genes in depth; retain zero counts and include each cell’s total UMIs in the observation model.", "fr": "Ajuster en détail les candidats ; conserver les zéros et inclure les UMI totaux de chaque cellule dans le modèle.", "es": "Ajustar candidatos en detalle; conservar ceros e incluir UMI totales de cada célula en el modelo.", "eu": "Doitu hautagaiak xeheki; gorde zero-kontaketak eta sartu zelula bakoitzeko UMI totalak ereduan."}, "相对丰度的比例性与对数比方差": {"en": "Proportionality and log-ratio variance of relative abundances", "fr": "Proportionnalité et variance des log-rapports d’abondances relatives", "es": "Proporcionalidad y varianza de log-cocientes de abundancias relativas", "eu": "Ugaritasun erlatiboen proportzionaltasuna eta log-ratioen bariantza"}, "矩阵行为观测、列为基因；单细胞应用按培养汇总效应与重抽样，单独报告零值敏感性。": {"en": "Rows are observations and columns are genes; summarize effects and resample by culture for single-cell applications, reporting zero sensitivity.", "fr": "Lignes : observations ; colonnes : gènes. Résumer et rééchantillonner par culture, en rapportant la sensibilité aux zéros.", "es": "Filas: observaciones; columnas: genes. Resumir y remuestrear por cultivo, informando sensibilidad a ceros.", "eu": "Errenkadak behaketak dira, zutabeak geneak; laburtu efektuak eta berriz lagindu kultiboka, zeroekiko sentikortasuna emanez."}, "按输入适配": {"en": "Adapt to available inputs", "fr": "Adapter aux entrées disponibles", "es": "Adaptar a entradas disponibles", "eu": "Eskuragarri dauden sarreretara egokitu"}, "分布分析": {"en": "Distribution analysis", "fr": "Analyse des distributions", "es": "Análisis de distribuciones", "eu": "Banaketen analisia"}, "原文与方法入口核对": {"en": "Primary source and method entry points checked", "fr": "Source primaire et points d’entrée vérifiés", "es": "Fuente primaria y puntos de entrada verificados", "eu": "Jatorrizko iturria eta metodo-sarrerak egiaztatuta"}, "方法与机制参考": {"en": "Method and mechanism reference", "fr": "Référence de méthode et de mécanisme", "es": "Referencia metodológica y mecanística", "eu": "Metodo eta mekanismo erreferentzia"}, "潜在分布的观测似然": {"en": "Observation likelihood for a latent distribution", "fr": "Vraisemblance d’observation d’une distribution latente", "es": "Verosimilitud observacional de una distribución latente", "eu": "Banaketa latentearen behaketa-egiantzekotasuna"}, "细胞i的观测UMI计数": {"en": "Observed UMI count in cell i", "fr": "Comptage UMI observé dans la cellule i", "es": "Recuento UMI observado en célula i", "eu": "i zelulan behatutako UMI kontaketa"}, "观测模型的逐细胞缩放量": {"en": "Cell-specific observation scaling", "fr": "Échelle d’observation par cellule", "es": "Escala observacional por célula", "eu": "Zelulako behaketa-eskala"}, "细胞群体的潜在表达分布": {"en": "Latent expression distribution across cells", "fr": "Distribution d’expression latente entre cellules", "es": "Distribución de expresión latente entre células", "eu": "Zelulen arteko adierazpen-banaketa latentea"}, "基因集合的合计方差分解": {"en": "Variance decomposition for summed transcripts", "fr": "Décomposition de variance des transcrits cumulés", "es": "Descomposición de varianza de transcritos conjuntos", "eu": "Transkriptu batuen bariantzaren deskonposizioa"}, "同一表达尺度上的基因g丰度": {"en": "Gene g abundance on a common expression scale", "fr": "Abondance du gène g sur une échelle commune", "es": "Abundancia del gen g en una escala común", "eu": "g genearen ugaritasuna adierazpen-eskala komun batean"}, "同一细胞分组的校正协方差": {"en": "Corrected covariance within the same cell group", "fr": "Covariance corrigée dans un même groupe cellulaire", "es": "Covarianza corregida en un mismo grupo celular", "eu": "Zelula-talde bereko kobariantza zuzendua"}, "先统一分子尺度与基因归属；协方差置零只定义代数比较基线。": {"en": "Align molecular scale and gene assignment; setting covariance to zero defines an algebraic comparison baseline.", "fr": "Harmoniser échelle moléculaire et attribution génique ; une covariance nulle définit une base de comparaison algébrique.", "es": "Alinear escala molecular y asignación génica; anular covarianza define una base algebraica de comparación.", "eu": "Lerrokatu eskala molekularra eta gene-esleipena; kobariantza zerora eramateak konparazio-oinarri algebraikoa definitzen du."}, "对数比方差与rho比例性": {"en": "Log-ratio variance and rho proportionality", "fr": "Variance des log-rapports et proportionnalité rho", "es": "Varianza de log-cocientes y proporcionalidad rho", "eu": "Log-ratioen bariantza eta rho proportzionaltasuna"}, "基于同一声明参照的对数丰度": {"en": "Log abundance using one declared reference", "fr": "Log-abondance avec une même référence déclarée", "es": "Log-abundancia con una referencia declarada común", "eu": "Erreferentzia komun adierazi bateko log-ugaritasuna"}, "基因对数比的方差": {"en": "Variance of the gene log ratio", "fr": "Variance du log-rapport génique", "es": "Varianza del log-cociente génico", "eu": "Geneen log-ratioaren bariantza"}, "声明零值处理；分母为零时比例性未定义。": {"en": "Specify zero handling; proportionality is undefined when the denominator is zero.", "fr": "Définir le traitement des zéros ; la proportionnalité est indéfinie si le dénominateur est nul.", "es": "Especificar ceros; la proporcionalidad no está definida si el denominador es cero.", "eu": "Zehaztu zeroen tratamendua; proportzionaltasuna definitu gabe dago izendatzailea zero denean."}, "密度／对数证据／有效样本量": {"en": "Density / log evidence / effective sample size", "fr": "Densité / log-évidence / taille effective", "es": "Densidad / log-evidencia / tamaño efectivo", "eu": "Dentsitatea / log-ebidentzia / lagin-tamaina eraginkorra"}, "联合估计均值与均值条件化变异，比较菌株、培养及状态内效应；对“仅噪音改变”候选同时报告均值等效区间与噪音效应区间。": {"en": "Jointly estimate means and mean-conditioned variability across strains, cultures and states; report mean-equivalence and noise-effect intervals for noise-only candidates.", "fr": "Estimer conjointement moyennes et variabilité conditionnelle selon souches, cultures et états ; rapporter intervalles d’équivalence des moyennes et effets de bruit pour les candidats à bruit seul.", "es": "Estimar conjuntamente medias y variabilidad condicionada entre cepas, cultivos y estados; informar intervalos de equivalencia de medias y efectos de ruido para candidatos de ruido exclusivo.", "eu": "Estimatu batera batezbestekoak eta batezbestekoaren araberako aldakortasuna andui, kultibo eta egoeren artean; eman batezbesteko-baliokidetasunaren eta zarata-efektuen tarteak zarata-soilik hautagaientzat."}, "按表达量、检出率与深度界定可比较基因；预先声明最小有意义的均值及变异效应。": {"en": "Define comparable genes by abundance, detection and depth; specify minimum meaningful mean and variability effects.", "fr": "Définir les gènes comparables selon abondance, détection et profondeur ; préciser les effets minimaux pertinents.", "es": "Definir genes comparables por abundancia, detección y profundidad; especificar efectos mínimos relevantes.", "eu": "Definitu gene alderagarriak ugaritasunaren, detekzioaren eta sakoneraren arabera; zehaztu gutxieneko efektu esanguratsuak."}, "固定计数层、培养层重抽样与检验集合；并列保存效应、区间和校正概率。": {"en": "Fix the count layer, culture-level resampling and test family; retain effects, intervals and adjusted probabilities together.", "fr": "Fixer couche de comptage, rééchantillonnage par culture et famille de tests ; conserver effets, intervalles et probabilités ajustées.", "es": "Fijar capa de recuentos, remuestreo por cultivo y familia de pruebas; conservar efectos, intervalos y probabilidades ajustadas.", "eu": "Finkatu kontaketa-geruza, kultiboko birlaginketa eta proba-familia; gorde efektuak, tarteak eta probabilitate doituak batera."}, "用均值等效证据区分稳定均值与低功效下的未检出差异。": {"en": "Use mean-equivalence evidence to distinguish stable means from underpowered differences.", "fr": "Utiliser l’équivalence des moyennes pour distinguer stabilité et différences insuffisamment détectées.", "es": "Usar equivalencia de medias para distinguir estabilidad y diferencias sin potencia suficiente.", "eu": "Erabili batezbesteko-baliokidetasuna egonkortasuna eta potentzia eskaseko aldeak bereizteko."}, "均值等效证据": {"en": "Evidence for mean equivalence", "fr": "Preuve d’équivalence des moyennes", "es": "Evidencia de equivalencia de medias", "eu": "Batezbestekoen baliokidetasunaren ebidentzia"}, "记录均值效应区间及其落入预设等效范围的证据，与噪音效应联合呈现。": {"en": "Record the mean-effect interval and evidence that it lies within a prespecified equivalence region, alongside the noise effect.", "fr": "Consigner l’intervalle de l’effet moyen et son appartenance à une zone d’équivalence prédéfinie, avec l’effet de bruit.", "es": "Registrar el intervalo del efecto medio y su pertenencia a una región de equivalencia predefinida, junto al efecto de ruido.", "eu": "Erregistratu batezbesteko-efektuaren tartea eta aurrez zehaztutako baliokidetasun-eremuan dagoen ebidentzia, zarata-efektuarekin batera."}, "log2倍数变化／概率": {"en": "Log2 fold change / probability", "fr": "Log2 du changement relatif / probabilité", "es": "Cambio relativo log2 / probabilidad", "eu": "Log2 aldaketa erlatiboa / probabilitatea"}, "用培养层分布检验筛选零值、尾部与多峰变化，再以潜在分布模型复核候选；尾部细胞回查分子支持、背景和双细胞。": {"en": "Screen zero, tail and multimodal changes with culture-aware distribution tests, then fit latent distributions to candidates; audit molecular support, background and doublets in tail cells.", "fr": "Détecter changements de zéros, queues et modes par des tests tenant compte des cultures, puis ajuster les distributions latentes ; contrôler support moléculaire, fond et doublets.", "es": "Detectar cambios en ceros, colas y modos con pruebas por cultivo y ajustar distribuciones latentes; auditar soporte molecular, fondo y dobletes.", "eu": "Bilatu zeroen, isatsen eta moduen aldaketak kultiboak kontuan hartuz, eta doitu banaketa latenteak; ikuskatu euskarri molekularra, hondoa eta dobleteak."}, "从现有数据校准深度、稀疏性和相关结构；分别改变均值、离散度、状态比例及捕获差异，比较菌株覆盖、培养数、细胞数和深度对检出能力的贡献。": {"en": "Calibrate depth, sparsity and correlation from existing data; vary means, dispersion, state proportions and capture differences separately, comparing strain coverage, cultures, cells and depth.", "fr": "Calibrer profondeur, sparsité et corrélation sur les données existantes ; varier séparément moyennes, dispersion, proportions d’états et capture, puis comparer couverture des souches, cultures, cellules et profondeur.", "es": "Calibrar profundidad, dispersión y correlación con datos existentes; variar por separado medias, dispersión, proporciones de estados y captura, comparando cobertura de cepas, cultivos, células y profundidad.", "eu": "Kalibratu sakonera, sakabanaketa eta korrelazioa lehendik dauden datuekin; aldatu batezbestekoak, dispertsioa, egoera-proportzioak eta kaptura bereiz, andui-estaldura, kultiboak, zelulak eta sakonera alderatuz."}, "固定待检测效应、测量模型和重抽样层级；输出功效—成本曲线及效应区间覆盖。": {"en": "Fix target effects, the measurement model and resampling hierarchy; report power–cost curves and effect-interval coverage.", "fr": "Fixer effets cibles, modèle de mesure et hiérarchie de rééchantillonnage ; rapporter courbes puissance–coût et couverture des intervalles.", "es": "Fijar efectos objetivo, modelo de medida y jerarquía de remuestreo; informar curvas potencia–coste y cobertura de intervalos.", "eu": "Finkatu xede-efektuak, neurketa-eredua eta birlaginketa-hierarkia; eman potentzia–kostu kurbak eta efektu-tarteen estaldura."}, "基因集合×菌株×培养×状态": {"en": "Gene set × strain × culture × state", "fr": "Ensemble de gènes × souche × culture × état", "es": "Conjunto génico × cepa × cultivo × estado", "eu": "Gene-multzoa × anduia × kultiboa × egoera"}, "均值与细胞间变异的联合推断": {"en": "Joint inference of means and cell-to-cell variability", "fr": "Inférence conjointe des moyennes et de la variabilité cellulaire", "es": "Inferencia conjunta de medias y variabilidad celular", "eu": "Batezbestekoen eta zelulen arteko aldakortasunaren inferentzia bateratua"}, "均值—变异依赖的模型校正": {"en": "Model-based correction of mean–variability dependence", "fr": "Correction modélisée de la dépendance moyenne–variabilité", "es": "Corrección modelada de dependencia media–variabilidad", "eu": "Batezbesteko–aldakortasun mendekotasunaren ereduzko zuzenketa"}, "BASiCS原文的C1数据重分析与修订": {"en": "Reanalysis and correction of C1 data in the BASiCS paper", "fr": "Réanalyse et correction des données C1 de l’article BASiCS", "es": "Reanálisis y corrección de datos C1 del artículo BASiCS", "eu": "BASiCS artikuluko C1 datuen berranalisia eta zuzenketa"}, "跨状态遗传效应共享": {"en": "Genetic-effect sharing across states", "fr": "Partage des effets génétiques entre états", "es": "Efectos genéticos compartidos entre estados", "eu": "Egoeren arteko efektu genetiko partekatuak"}, "联合估计状态效应、后验标准差和符号错误率，比较方向与强度。": {"en": "Jointly estimate state effects, posterior deviations and false-sign rates; compare direction and magnitude.", "fr": "Estimer conjointement effets, écarts postérieurs et taux de signe erroné ; comparer direction et amplitude.", "es": "Estimar efectos, desviaciones posteriores y tasas de signo falso; comparar dirección y magnitud.", "eu": "Estimatu egoera-efektuak, ondorengo desbideratzeak eta zeinu okerren tasak; konparatu norabidea eta magnitudea."}, "协同表达与协方差QTL": {"en": "Co-expression and covariance QTLs", "fr": "QTL de coexpression et covariance", "es": "QTL de coexpresión y covarianza", "eu": "Ko-espresio eta kobariantza QTLak"}, "检验菌株内、状态条件化的基因对协方差或相关性的遗传效应。": {"en": "Test genetic effects on within-strain, state-conditioned gene-pair covariance or correlation.", "fr": "Tester les effets génétiques sur la covariance ou corrélation entre gènes par souche et état.", "es": "Evaluar efectos genéticos sobre covarianza o correlación entre genes por cepa y estado.", "eu": "Probatu efektu genetikoak andui eta egoera bakoitzeko gene-bikoteen kobariantzan edo korrelazioan."}, "可定相分子覆盖与等位冲突": {"en": "Phased-molecule coverage and allelic conflicts", "fr": "Couverture moléculaire phasée et conflits alléliques", "es": "Cobertura molecular faseada y conflictos alélicos", "eu": "Fasekatutako molekulen estaldura eta alelo-gatazkak"}, "记录各单倍型的独立UMI、未定相分子及同分子位点冲突。": {"en": "Record independent haplotype UMIs, unphased molecules and within-molecule SNP conflicts.", "fr": "Consigner UMI indépendants par haplotype, molécules non phasées et conflits entre sites.", "es": "Registrar UMI por haplotipo, moléculas sin fase y conflictos entre sitios de una molécula.", "eu": "Erregistratu haplotipoen UMI independenteak, fasekatu gabeko molekulak eta molekula barruko SNP gatazkak."}, "等位失衡的状态依赖": {"en": "State dependence of allelic imbalance", "fr": "Dépendance du déséquilibre allélique à l’état", "es": "Dependencia del desequilibrio alélico del estado", "eu": "Alelo-desorekaren egoera-mendekotasuna"}, "比较持续、状态依赖和联合等位失衡，保存等位比例曲线及不确定性。": {"en": "Compare homogeneous, state-dependent and joint imbalance; retain allelic-rate curves and uncertainty.", "fr": "Comparer déséquilibre homogène, dépendant de l’état et conjoint ; conserver courbes et incertitude.", "es": "Comparar desequilibrio homogéneo, dependiente del estado y conjunto; conservar curvas e incertidumbre.", "eu": "Konparatu desoreka homogeneoa, egoeraren araberakoa eta bateratua; gorde kurbak eta ziurgabetasuna."}, "配对等位噪音差异": {"en": "Paired allelic-noise contrast", "fr": "Contraste du bruit allélique apparié", "es": "Contraste de ruido alélico pareado", "eu": "Alelo parekatuen zarata-kontrastea"}, "在相同细胞中联合估计两个等位的均值、离散度和协变，比较均值调整后的噪音。": {"en": "Jointly estimate allelic means, dispersion and covariance in the same cells; compare mean-adjusted noise.", "fr": "Estimer moyennes, dispersions et covariance alléliques dans les mêmes cellules ; comparer le bruit ajusté.", "es": "Estimar medias, dispersiones y covarianza alélicas en las mismas células; comparar ruido ajustado.", "eu": "Estimatu aleloen batezbestekoak, sakabanaketak eta kobariantza zelula beretan; konparatu zarata doitua."}, "变异集合支持与关联": {"en": "Variant-set support and association", "fr": "Support et association des groupes de variants", "es": "Soporte y asociación de conjuntos de variantes", "eu": "Aldaera multzoen euskarria eta asoziazioa"}, "同时记录变异数、携带菌株、缺失模式、集合检验和逐携带者敏感性。": {"en": "Record variants, carrier strains, missingness, set tests and leave-one-carrier sensitivity.", "fr": "Consigner variants, souches porteuses, données manquantes, tests et sensibilité au retrait des porteurs.", "es": "Registrar variantes, cepas portadoras, datos faltantes, pruebas y sensibilidad al excluir portadores.", "eu": "Erregistratu aldaerak, andui eramaileak, datu faltak, probak eta eramaileak kentzearen sentikortasuna."}, "噪音遗传互作与组合支持": {"en": "Noise epistasis and genotype-combination support", "fr": "Épistasie du bruit et support génotypique", "es": "Epistasis del ruido y soporte genotípico", "eu": "Zarataren epistasia eta genotipo-euskarria"}, "记录各基因型组合的菌株数、互作效应及相对加性模型的预测增益。": {"en": "Record strain support per genotype combination, interaction effects and predictive gain over an additive model.", "fr": "Consigner support par combinaison, effets d’interaction et gain prédictif sur le modèle additif.", "es": "Registrar soporte por combinación, interacción y mejora predictiva frente al modelo aditivo.", "eu": "Erregistratu konbinazioaren andui-euskarria, interakzioa eta eredu gehigarriaren gaineko iragarpen-hobekuntza."}, "遗传方差分区与培养重复性": {"en": "Genetic variance partitioning and culture repeatability", "fr": "Partition de variance génétique et répétabilité", "es": "Partición de varianza genética y repetibilidad", "eu": "Bariantza genetikoaren partizioa eta errepikakortasuna"}, "区分标记捕获的加性遗传方差、稳定菌株差异、培养方差和性状估计误差。": {"en": "Separate marker-captured additive variance, stable strain differences, culture variance and trait-estimation error.", "fr": "Séparer variance additive capturée, différences stables entre souches, variance de culture et erreur d’estimation.", "es": "Separar varianza aditiva capturada, diferencias estables entre cepas, varianza de cultivo y error de estimación.", "eu": "Bereizi bariantza gehigarri genetikoa, anduien alde egonkorrak, kultura-bariantza eta estimazio-errorea."}, "噪音反应规范与跨环境稳定性": {"en": "Noise reaction norms and environmental stability", "fr": "Normes de réaction du bruit et stabilité environnementale", "es": "Normas de reacción del ruido y estabilidad ambiental", "eu": "Zarataren erreakzio-arauak eta ingurumen-egonkortasuna"}, "比较重复测量菌株的噪音环境响应、排序保持和基因型×环境效应。": {"en": "Compare noise responses, rank preservation and genotype-by-environment effects across repeatedly measured strains.", "fr": "Comparer réponses du bruit, maintien des rangs et effets génotype–environnement dans les souches répétées.", "es": "Comparar respuestas del ruido, conservación de rangos y efectos genotipo–ambiente en cepas repetidas.", "eu": "Konparatu zarataren erantzunak, ordena eta genotipo–ingurune efektuak errepikatutako anduietan."}, "接入匹配基因型与相应性状后启用": {"en": "Enable with matched genotypes and traits", "fr": "Activer avec génotypes et caractères appariés", "es": "Activar con genotipos y rasgos emparejados", "eu": "Aktibatu genotipo eta ezaugarri parekatuekin"}, "协调的效应、标准误与共享样本误差相关": {"en": "Harmonized effects, standard errors and shared-sample error correlations", "fr": "Effets harmonisés, erreurs-types et corrélations liées aux échantillons partagés", "es": "Efectos armonizados, errores estándar y correlaciones por muestras compartidas", "eu": "Efektu bateratuak, errore estandarrak eta lagin partekatuen errore-korrelazioak"}, "从数据学习协方差；用全部检验或随机子集拟合混合分布。": {"en": "Learn covariance patterns; fit the mixture with all tests or a random subset.", "fr": "Apprendre les covariances ; ajuster sur tous les tests ou un sous-ensemble aléatoire.", "es": "Aprender covarianzas; ajustar con todas las pruebas o una muestra aleatoria.", "eu": "Ikasi kobariantzak; doitu nahastea proba guztiekin edo ausazko azpimultzoarekin."}, "多状态遗传效应的联合估计": {"en": "Joint estimation of genetic effects across states", "fr": "Estimation conjointe des effets génétiques entre états", "es": "Estimación conjunta de efectos genéticos entre estados", "eu": "Egoeren arteko efektu genetikoen estimazio bateratua"}, "定相杂合位点、单分子等位计数与细胞状态": {"en": "Phased heterozygous sites, molecular allelic counts and cell states", "fr": "Sites hétérozygotes phasés, comptages alléliques moléculaires et états cellulaires", "es": "Sitios heterocigotos faseados, recuentos alélicos moleculares y estados celulares", "eu": "Gune heterozigoto fasekatuak, aleloen molekula-kontaketak eta zelula-egoerak"}, "状态由独立特征构建；基线等位比例匹配拷贝数与定相方向。": {"en": "Build states from independent features; match baseline allelic rates to copy number and phase orientation.", "fr": "Construire les états avec des caractéristiques indépendantes ; adapter le taux basal au nombre de copies et au phasage.", "es": "Construir estados con características independientes; ajustar proporción basal al número de copias y fase.", "eu": "Eraiki egoerak ezaugarri independenteekin; egokitu oinarrizko alelo-proportzioak kopia-kopuruari eta faseari."}, "状态依赖的等位表达失衡": {"en": "State-dependent allelic expression imbalance", "fr": "Déséquilibre allélique d’expression dépendant de l’état", "es": "Desequilibrio alélico dependiente del estado", "eu": "Egoeraren araberako alelo-espresioaren desoreka"}, "原始计数、菌株身份、基因型、亲缘和协变量": {"en": "Raw counts, strain identity, genotypes, relatedness and covariates", "fr": "Comptages bruts, identité de souche, génotypes, parenté et covariables", "es": "Recuentos brutos, identidad de cepa, genotipos, parentesco y covariables", "eu": "Kontaketa gordinak, andui-identitatea, genotipoak, ahaidetasuna eta kobariableak"}, "建模同菌株多细胞与菌株间亲缘；按实际倍性编码。": {"en": "Model cells nested in strains and between-strain relatedness; encode observed ploidy.", "fr": "Modéliser cellules imbriquées et parenté entre souches ; coder la ploïdie observée.", "es": "Modelar células dentro de cepas y parentesco; codificar ploidía observada.", "eu": "Modelatu andui barruko zelulak eta anduien ahaidetasuna; kodetu ikusitako ploidia."}, "记录offset尺度及变异集合；该模型估计计数均值的遗传效应。": {"en": "Record offset scale and variant sets; this model estimates genetic effects on mean counts.", "fr": "Consigner l’offset et les groupes de variants ; le modèle estime les effets sur le comptage moyen.", "es": "Registrar offset y conjuntos; el modelo estima efectos sobre recuentos medios.", "eu": "Erregistratu offseta eta aldaera multzoak; ereduak batez besteko kontaketaren efektuak estimatzen ditu."}, "均值eQTL、集合检验与基因级结果": {"en": "Mean eQTLs, set tests and gene-level results", "fr": "eQTL de moyenne, tests agrégés et résultats par gène", "es": "eQTL de media, pruebas agregadas y resultados por gen", "eu": "Batezbestekoaren eQTLak, multzo-probak eta gene-mailako emaitzak"}, "细胞计数eQTL与稀有变异集合检验": {"en": "Cell-count eQTL and rare-variant set tests", "fr": "eQTL de comptage et tests de variants rares", "es": "eQTL de recuentos y pruebas de variantes raras", "eu": "Zelula-kontaketaren eQTL eta aldaera arraroen probak"}, "噪音性状、基因型、亲缘与酵母变异集合": {"en": "Noise traits, genotypes, relatedness and yeast variant sets", "fr": "Caractères de bruit, génotypes, parenté et groupes de variants de levure", "es": "Rasgos de ruido, genotipos, parentesco y conjuntos de variantes de levadura", "eu": "Zarata-ezaugarriak, genotipoak, ahaidetasuna eta legamiaren aldaera multzoak"}, "按酵母启动子或功能注释定义集合；记录频率范围、权重和携带菌株。": {"en": "Define sets by yeast promoters or functional annotation; record frequency ranges, weights and carriers.", "fr": "Définir les groupes par promoteurs ou fonctions de levure ; consigner fréquences, poids et porteurs.", "es": "Definir conjuntos por promotores o funciones de levadura; registrar frecuencias, pesos y portadores.", "eu": "Definitu multzoak legamiaren sustatzaile edo funtzioen arabera; erregistratu maiztasunak, pisuak eta eramaileak."}, "核对性状尺度与残差；培养重抽样传播噪音估计误差。": {"en": "Check trait scale and residuals; propagate noise-estimation error by culture resampling.", "fr": "Vérifier échelle et résidus ; propager l’erreur par rééchantillonnage des cultures.", "es": "Comprobar escala y residuos; propagar error mediante remuestreo de cultivos.", "eu": "Egiaztatu eskala eta hondarrak; hedatu errorea kulturen birlaginketarekin."}, "亲缘校正的变异集合关联": {"en": "Relatedness-adjusted variant-set association", "fr": "Association de groupes ajustée sur la parenté", "es": "Asociación de conjuntos ajustada por parentesco", "eu": "Ahaidetasunaren arabera doitutako multzoen asoziazioa"}, "遗传比较以菌株为单位；培养重复估计重现性，细胞估计菌株内分布。": {"en": "Genetic comparisons use strains; cultures estimate reproducibility and cells estimate within-strain distributions.", "fr": "Les comparaisons génétiques portent sur les souches ; cultures et cellules estiment reproductibilité et distributions internes.", "es": "Las comparaciones genéticas usan cepas; cultivos y células estiman reproducibilidad y distribuciones internas.", "eu": "Konparazio genetikoen unitatea anduia da; kulturek erreproduzigarritasuna eta zelulek andui barruko banaketak estimatzen dituzte."}, "共享遗传效应、协同噪音与共定位": {"en": "Shared genetic effects, coordinated noise and colocalization", "fr": "Effets partagés, bruit coordonné et colocalisation", "es": "Efectos compartidos, ruido coordinado y colocalización", "eu": "Efektu partekatuak, zarata koordinatua eta kolokalizazioa"}, "同一位点是否共同改变均值、噪音、基因协变和状态占据？": {"en": "Does a locus jointly alter means, noise, gene covariance and state occupancy?", "fr": "Un locus modifie-t-il moyenne, bruit, covariance et occupation des états ?", "es": "¿Un locus modifica media, ruido, covarianza y ocupación de estados?", "eu": "Lokus batek batera aldatzen al ditu batezbestekoa, zarata, kobariantza eta egoera-okupazioa?"}, "分别构建均值、噪音、协方差和状态比例性状；mashr整合跨状态效应，再用匹配LD精细定位并比较共定位。": {"en": "Construct mean, noise, covariance and state-proportion traits; combine state effects with mashr, then fine-map and test colocalization using matched LD.", "fr": "Construire moyenne, bruit, covariance et proportions ; combiner les effets avec mashr, puis cartographier finement et colocaliser avec LD apparié.", "es": "Construir media, ruido, covarianza y proporciones; combinar efectos con mashr y realizar mapeo fino y colocalización con LD emparejado.", "eu": "Eraiki batezbesteko, zarata, kobariantza eta proportzioak; bateratu efektuak mashr-rekin eta egin mapa fina eta kolokalizazioa LD parekatuarekin."}, "等位特异噪音与状态调控": {"en": "Allele-specific noise and state regulation", "fr": "Bruit allélique et régulation selon l’état", "es": "Ruido alélico y regulación por estado", "eu": "Aleloaren araberako zarata eta egoera-erregulazioa"}, "同细胞内两个等位的表达稳定性和状态响应是否不同？": {"en": "Do the two alleles within a cell differ in stability and state response?", "fr": "Les deux allèles d’une cellule diffèrent-ils par stabilité et réponse à l’état ?", "es": "¿Difieren los dos alelos de una célula en estabilidad y respuesta al estado?", "eu": "Zelula bereko bi aleloek egonkortasun eta egoera-erantzun desberdinak al dituzte?"}, "在杂合菌株中建立单倍型UMI矩阵；scDALI估计状态依赖等位失衡，再在相同细胞中比较均值调整后的等位噪音。": {"en": "Build haplotype UMI matrices in heterozygous strains; use scDALI for state-dependent imbalance and compare mean-adjusted allelic noise in the same cells.", "fr": "Construire les matrices UMI par haplotype ; utiliser scDALI et comparer le bruit allélique ajusté dans les mêmes cellules.", "es": "Construir matrices UMI por haplotipo; usar scDALI y comparar ruido alélico ajustado en las mismas células.", "eu": "Eraiki haplotipoen UMI matrizeak; erabili scDALI eta konparatu aleloen zarata doitua zelula beretan."}, "稀有调控变异与集合效应": {"en": "Rare regulatory variants and set effects", "fr": "Variants régulateurs rares et effets de groupes", "es": "Variantes reguladoras raras y efectos de conjuntos", "eu": "Aldaera erregulatzaile arraroak eta multzoen efektuak"}, "多个低频变异是否共同改变基因或程序的表达稳定性？": {"en": "Do low-frequency variants jointly alter gene or program stability?", "fr": "Des variants peu fréquents modifient-ils ensemble la stabilité d’un gène ou programme ?", "es": "¿Variantes poco frecuentes alteran conjuntamente la estabilidad de un gen o programa?", "eu": "Maiztasun txikiko aldaerek batera aldatzen al dute gene edo programa baten egonkortasuna?"}, "按酵母启动子、编码区或功能集合归组变异；SAIGE-QTL检验细胞计数均值，GMMAT检验菌株噪音性状，并检查携带者支持与培养重现性。": {"en": "Group variants by yeast promoters, coding regions or functions; use SAIGE-QTL for mean counts and GMMAT for strain noise, then assess carriers and culture reproducibility.", "fr": "Regrouper par promoteurs, régions codantes ou fonctions ; tester moyenne avec SAIGE-QTL et bruit avec GMMAT, puis examiner porteurs et reproductibilité.", "es": "Agrupar por promotores, regiones codificantes o funciones; probar medias con SAIGE-QTL y ruido con GMMAT, revisando portadores y reproducibilidad.", "eu": "Taldekatu sustatzaile, kodetze-eskualde edo funtzioetan; probatu batezbestekoak SAIGE-QTL-rekin eta zarata GMMAT-rekin, eramaileak eta erreproduzigarritasuna aztertuz."}, "表达噪音的遗传互作": {"en": "Genetic interactions controlling expression noise", "fr": "Interactions génétiques du bruit d’expression", "es": "Interacciones genéticas del ruido de expresión", "eu": "Espresio-zarataren interakzio genetikoak"}, "噪音QTL的效应是否取决于另一个遗传位点？": {"en": "Does a noise-QTL effect depend on a second locus?", "fr": "L’effet d’un QTL de bruit dépend-il d’un second locus ?", "es": "¿Depende el efecto de un QTL de ruido de otro locus?", "eu": "Zarata-QTL baten efektua beste lokus baten araberakoa al da?"}, "从已有QTL和调控关系定义位点对，在亲缘模型中比较加性与互作项，以留出菌株检验预测增益。": {"en": "Define locus pairs from QTLs and regulatory relationships; compare additive and interaction models with relatedness, then validate predictive gain in held-out strains.", "fr": "Définir les paires par QTL et régulation ; comparer modèles additif et interactif avec parenté, puis valider sur des souches réservées.", "es": "Definir pares desde QTL y regulación; comparar aditividad e interacción con parentesco y validar en cepas reservadas.", "eu": "Definitu bikoteak QTL eta erregulaziotik; konparatu eredu gehigarri eta interaktiboa ahaidetasunarekin eta balioztatu gordetako anduietan."}, "保留两个位点的主效应；声明位点对、性状尺度和多重检验集合。": {"en": "Include both main effects; declare locus pairs, trait scale and the multiple-testing family.", "fr": "Inclure les deux effets principaux ; définir paires, échelle et famille de tests.", "es": "Incluir ambos efectos principales; definir pares, escala y familia de pruebas.", "eu": "Sartu bi efektu nagusiak; definitu bikoteak, eskala eta proba anitzen multzoa."}, "建立均值、噪音、尾部和状态比例性状，分离遗传方差、培养重复性与测量误差；分别检验局部、远端和状态组成QTL。": {"en": "Build mean, noise, tail and state-proportion traits; separate genetic variance, culture repeatability and measurement error; map local, distal and composition QTLs.", "fr": "Construire moyenne, bruit, queues et proportions ; séparer variance génétique, répétabilité et erreur ; cartographier QTL locaux, distaux et de composition.", "es": "Construir media, ruido, colas y proporciones; separar varianza genética, repetibilidad y error; mapear QTL locales, distales y de composición.", "eu": "Eraiki batezbesteko, zarata, isats eta proportzioen ezaugarriak; bereizi bariantza genetikoa, errepikakortasuna eta errorea; mapatu tokiko, urruneko eta konposizio-QTLak."}, "遗传力的分母、性状尺度与目标群体随模型一并记录。": {"en": "Record the heritability denominator, trait scale and target population with the model.", "fr": "Consigner dénominateur d’héritabilité, échelle et population cible avec le modèle.", "es": "Registrar denominador de heredabilidad, escala y población objetivo con el modelo.", "eu": "Erregistratu heredagarritasunaren izendatzailea, eskala eta xede-populazioa ereduarekin."}, "联合估计持续遗传效应、周期位置和连续响应状态的交互；有匹配处理时同时拟合离散条件与连续响应，区分状态占据和状态内效应。": {"en": "Estimate persistent genetic effects and interactions with cycle and continuous response; with matched treatments, model discrete condition and response to separate occupancy and within-state effects.", "fr": "Estimer effets persistants et interactions avec cycle et réponse ; avec traitements appariés, séparer condition, occupation et effets internes aux états.", "es": "Estimar efectos persistentes e interacciones con ciclo y respuesta; con tratamientos emparejados separar condición, ocupación y efectos dentro de estados.", "eu": "Estimatu efektu iraunkorrak eta zikloaren eta erantzunaren interakzioak; tratamendu parekatuekin bereizi baldintza, okupazioa eta egoera barruko efektuak."}, "响应分数采用培养或菌株留出训练；目标基因从其自身状态评分中排除。": {"en": "Train response scores with culture or strain holdouts; exclude the tested gene from its own state score.", "fr": "Apprendre les scores avec cultures ou souches réservées ; exclure le gène testé de son propre score.", "es": "Entrenar puntuaciones reservando cultivos o cepas; excluir el gen probado de su propio estado.", "eu": "Entrenatu puntuazioak kulturak edo anduiak gordez; baztertu gene probatua bere egoera-puntuaziotik."}, "持续效应、状态交互和环境交互分别报告估计对象与输入。": {"en": "Report persistent, state-interaction and environment-interaction estimands and inputs separately.", "fr": "Rapporter séparément objets et entrées des effets persistants et interactions d’état ou d’environnement.", "es": "Informar por separado estimandos y entradas de efectos persistentes e interacciones de estado o ambiente.", "eu": "Eman bereiz efektu iraunkorren eta egoera- edo ingurune-interakzioen estimazio-objektuak eta sarrerak."}, "将条件化噪音关联到亲缘、谱系和生态来源；比较谱系内分化、跨谱系重现与环境反应规范，再整合已有选择和适应度证据解释遗传缓冲与可塑性。": {"en": "Relate conditioned noise to relatedness, lineages and ecology; compare within-lineage divergence, cross-lineage replication and reaction norms, then integrate existing selection and fitness evidence for buffering and plasticity.", "fr": "Relier le bruit à la parenté, aux lignées et à l’écologie ; comparer divergence, réplication et normes de réaction, puis intégrer sélection et fitness.", "es": "Relacionar ruido con parentesco, linajes y ecología; comparar divergencia, replicación y normas de reacción e integrar selección y aptitud.", "eu": "Lotu zarata ahaidetasunarekin, leinuekin eta ekologiarekin; konparatu dibergentzia, errepikapena eta erreakzio-arauak, eta integratu hautespena eta egokitasuna."}, "表达轨迹描述状态顺序；群体历史使用已有基因组亲缘或谱系。": {"en": "Expression trajectories describe state order; population history uses genomic relatedness or lineages.", "fr": "Les trajectoires décrivent l’ordre des états ; l’histoire de population utilise parenté génomique ou lignées.", "es": "Las trayectorias describen orden de estados; la historia poblacional usa parentesco genómico o linajes.", "eu": "Espresio-ibilbideek egoeren ordena deskribatzen dute; populazioaren historiak ahaidetasun genomikoa edo leinuak erabiltzen ditu."}, "联合估计多条件效应，学习共享模式并保留效应异质性。": {"en": "Jointly estimate effects across conditions, learning shared patterns and effect heterogeneity.", "fr": "Estimer conjointement les effets entre conditions, leur partage et leur hétérogénéité.", "es": "Estimar efectos entre condiciones, patrones compartidos y heterogeneidad.", "eu": "Estimatu baldintzen arteko efektuak, eredu partekatuak eta heterogeneotasuna."}, "用单细胞表达估计个体网络并定位改变基因共表达的遗传变异。": {"en": "Use single-cell expression to estimate individual networks and map genetic changes in co-expression.", "fr": "Estimer des réseaux individuels avec le single-cell et cartographier les effets génétiques sur la coexpression.", "es": "Estimar redes individuales con expresión unicelular y mapear cambios genéticos de coexpresión.", "eu": "Estimatu banakoen sareak zelula bakarreko espresioarekin eta mapatu ko-espresioaren aldaketa genetikoak."}, "以总计数定义状态，以等位计数检验持续和状态依赖的调控差异。": {"en": "Define states from total counts and test homogeneous and state-dependent regulation with allelic counts.", "fr": "Définir les états par comptages totaux et tester la régulation homogène ou dépendante de l’état avec les allèles.", "es": "Definir estados con recuentos totales y probar regulación homogénea o dependiente del estado con alelos.", "eu": "Definitu egoerak guztizko kontaketekin eta probatu erregulazio homogeneoa edo egoeraren araberakoa aleloekin."}, "在亲缘混合模型中实现负荷、SKAT、SKAT-O及混合型变异集合检验。": {"en": "Implement burden, SKAT, SKAT-O and hybrid set tests in relatedness-aware mixed models.", "fr": "Implémenter tests de charge, SKAT, SKAT-O et hybrides dans des modèles mixtes avec parenté.", "es": "Implementar carga, SKAT, SKAT-O y pruebas híbridas en modelos mixtos con parentesco.", "eu": "Inplementatu zama, SKAT, SKAT-O eta proba hibridoak ahaidetasuneko eredu mistoetan."}, "Poisson混合模型直接分析细胞计数，处理同个体重复观测及亲缘，支持单变异和集合检验。": {"en": "A Poisson mixed model analyzes cell counts with repeated observations and relatedness, supporting variant and set tests.", "fr": "Un modèle de Poisson mixte analyse les comptages avec répétitions et parenté, pour variants et groupes.", "es": "Un modelo mixto de Poisson analiza recuentos con repeticiones y parentesco, para variantes y conjuntos.", "eu": "Poisson eredu mistoak kontaketak aztertzen ditu errepikapenekin eta ahaidetasunarekin, aldaera eta multzoetarako."}, "在酵母分离群体中解析表达量的远端调控热点与遗传互作。": {"en": "Dissect distal regulatory hotspots and genetic interactions for expression levels in yeast segregants.", "fr": "Analyser les points chauds distaux et interactions génétiques de l’expression chez les ségrégants de levure.", "es": "Analizar puntos reguladores distales e interacciones de expresión en segregantes de levadura.", "eu": "Aztertu urruneko erregulazio-guneak eta espresioaren interakzio genetikoak legamiaren segregatzaileetan."}, "将表达均值和噪音共同纳入适应度分析，提供噪音进化研究的概念参照。": {"en": "Analyze mean expression and noise jointly with fitness, providing a conceptual reference for noise evolution.", "fr": "Analyser conjointement moyenne, bruit et fitness comme référence pour l’évolution du bruit.", "es": "Analizar conjuntamente media, ruido y aptitud como referencia para evolución del ruido.", "eu": "Aztertu batera batezbestekoa, zarata eta egokitasuna, zarataren eboluziorako erreferentzia gisa."}, "联合离散处理与连续细胞响应，识别随响应状态变化的均值eQTL。": {"en": "Combine discrete treatment and continuous cellular response to identify response-dependent mean eQTLs.", "fr": "Combiner traitement discret et réponse continue pour identifier les eQTL de moyenne dépendant de la réponse.", "es": "Combinar tratamiento discreto y respuesta continua para identificar eQTL de media dependientes de respuesta.", "eu": "Bateratu tratamendu diskretua eta erantzun jarraitua, erantzunaren araberako batezbestekoaren eQTLak identifikatzeko."}, "比较酵母环境间的表达可塑性及表达—适应度关系，为噪音反应规范提供设计参照。": {"en": "Compare yeast expression plasticity and expression–fitness relationships across environments to inform noise reaction-norm design.", "fr": "Comparer plasticité d’expression et relation à la fitness entre environnements pour orienter les normes de réaction du bruit.", "es": "Comparar plasticidad y relaciones expresión–aptitud entre ambientes para diseñar normas de reacción del ruido.", "eu": "Konparatu espresio-plastikotasuna eta espresio–egokitasun erlazioak inguruneetan, zarataren erreakzio-arauak diseinatzeko."}, "原文与官方方法核对": {"en": "Primary article and official method checked", "fr": "Article original et méthode officielle vérifiés", "es": "Artículo original y método oficial verificados", "eu": "Jatorrizko artikulua eta metodo ofiziala egiaztatuak"}, "分别编码SNP、拷贝数和基因存在缺失；多倍体分支保留实际剂量，二倍体分支可区分加性与显性效应。": {"en": "Encode SNPs, copy number and gene presence/absence separately; retain observed dosage in polyploids and distinguish additive from dominance effects in diploids.", "fr": "Coder séparément SNP, nombre de copies et présence/absence ; conserver le dosage polyploïde et distinguer effets additifs et dominance chez les diploïdes.", "es": "Codificar SNP, copias y presencia/ausencia por separado; conservar dosis poliploide y distinguir aditividad y dominancia en diploides.", "eu": "Kodetu SNPak, kopia-kopurua eta presentzia/absentzia bereiz; gorde poliploideen dosia eta bereizi efektu gehigarriak eta dominantzia diploideetan."}, "Hom调用的原生pvalues，映射为项目列pvalues_hom。": {"en": "Native pvalues from the Hom call, mapped to project column pvalues_hom.", "fr": "pvalues natifs de l’appel Hom, renommés pvalues_hom dans le projet.", "es": "pvalues nativos de la llamada Hom, asignados a pvalues_hom en el proyecto.", "eu": "Hom deiaren jatorrizko pvalues, proiektuko pvalues_hom zutabera esleituak."}, "Het调用的原生pvalues，映射为项目列pvalues_het。": {"en": "Native pvalues from the Het call, mapped to project column pvalues_het.", "fr": "pvalues natifs de l’appel Het, renommés pvalues_het dans le projet.", "es": "pvalues nativos de la llamada Het, asignados a pvalues_het en el proyecto.", "eu": "Het deiaren jatorrizko pvalues, proiektuko pvalues_het zutabera esleituak."}, "Joint调用的原生pvalues，映射为项目列pvalues_joint。": {"en": "Native pvalues from the Joint call, mapped to project column pvalues_joint.", "fr": "pvalues natifs de l’appel Joint, renommés pvalues_joint dans le projet.", "es": "pvalues nativos de la llamada Joint, asignados a pvalues_joint en el proyecto.", "eu": "Joint deiaren jatorrizko pvalues, proiektuko pvalues_joint zutabera esleituak."}, "插值调用返回的原生posterior_mean。": {"en": "Native posterior_mean returned by interpolation.", "fr": "posterior_mean natif renvoyé par interpolation.", "es": "posterior_mean nativo devuelto por interpolación.", "eu": "Interpolazioak itzulitako jatorrizko posterior_mean."}, "插值调用返回的原生posterior_var。": {"en": "Native posterior_var returned by interpolation.", "fr": "posterior_var natif renvoyé par interpolation.", "es": "posterior_var nativo devuelto por interpolación.", "eu": "Interpolazioak itzulitako jatorrizko posterior_var."}, "在同一杂合菌株、培养及定相方向内拟合；跨菌株汇总先协调相同变异与效应等位，其他单倍型比较分别保留。": {"en": "Fit within each heterozygous strain, culture and phase orientation; align identical variants and effect alleles before cross-strain summaries, retaining other haplotype contrasts separately.", "fr": "Ajuster par souche hétérozygote, culture et orientation de phase ; harmoniser variants identiques et allèles d’effet avant synthèse, en conservant les autres contrastes séparés.", "es": "Ajustar por cepa heterocigota, cultivo y orientación de fase; armonizar variantes idénticas y alelos de efecto antes del resumen, conservando otros contrastes por separado.", "eu": "Doitu andui heterozigoto, kultura eta fase-norabide bakoitzean; bateratu aldaera berak eta efektu-aleloak laburpenaren aurretik, beste haplotipo-kontrasteak bereiz gordez."}, "导入均值、噪音、协方差和状态比例的关联结果；mashr估计跨状态共享，SuSiE和coloc使用原始关联系数、标准误及匹配LD。": {"en": "Import association results for means, noise, covariance and state proportions; use mashr for cross-state sharing and original association coefficients, standard errors and matched LD for SuSiE and coloc.", "fr": "Importer les associations de moyenne, bruit, covariance et proportions ; utiliser mashr pour le partage, puis les coefficients originaux, erreurs-types et LD apparié pour SuSiE et coloc.", "es": "Importar asociaciones de media, ruido, covarianza y proporciones; usar mashr para compartir efectos y coeficientes originales, errores estándar y LD emparejado para SuSiE y coloc.", "eu": "Inportatu batezbesteko, zarata, kobariantza eta proportzioen asoziazioak; erabili mashr partekatzea aztertzeko, eta jatorrizko koefizienteak, errore estandarrak eta LD parekatua SuSiE eta coloc-erako."}, "默认导入已有协方差QTL；重新估计该性状及关联时，需原始计数、样本身份、细胞状态、基因型与亲缘矩阵。": {"en": "Import existing covariance QTLs by default; re-estimating traits and associations requires raw counts, sample identity, cell states, genotypes and kinship.", "fr": "Importer les QTL de covariance existants ; leur réestimation exige comptages bruts, identité des échantillons, états, génotypes et parenté.", "es": "Importar QTL de covarianza existentes; reestimarlos requiere recuentos brutos, identidad, estados, genotipos y parentesco.", "eu": "Inportatu dauden kobariantza-QTLak lehenespenez; berriz estimatzeko kontaketa gordinak, laginen identitatea, egoerak, genotipoak eta ahaidetasuna behar dira."}, "mashr后验收缩值用于效应共享；精细定位和共定位读取未收缩的关联估计、标准误或z值与对应LD。": {"en": "Use mashr posterior shrinkage for effect sharing; fine mapping and colocalization read unshrunk association estimates, standard errors or z-scores and corresponding LD.", "fr": "Utiliser les postérieurs mashr pour le partage ; cartographie fine et colocalisation utilisent les estimations non rétractées, erreurs-types ou scores z et le LD correspondant.", "es": "Usar posteriores mashr para efectos compartidos; el mapeo fino y la colocalización usan estimaciones sin contracción, errores estándar o valores z y LD correspondiente.", "eu": "Erabili mashr ondorengo estimazioak efektuak partekatzeko; mapa finak eta kolokalizazioak uzkurtu gabeko estimazioak, errore estandarrak edo z puntuazioak eta dagokion LD erabiltzen dituzte."}, "协调各状态的原始关联结果，包含已有协方差QTL、样本重叠和等位方向。": {"en": "Harmonize original state-specific associations, including existing covariance QTLs, sample overlap and allele orientation.", "fr": "Harmoniser les associations originales par état, y compris QTL de covariance, chevauchement des échantillons et orientation allélique.", "es": "Armonizar asociaciones originales por estado, incluidos QTL de covarianza, solapamiento de muestras y orientación alélica.", "eu": "Bateratu egoera bakoitzeko jatorrizko asoziazioak, kobariantza-QTLak, laginen gainjartzea eta alelo-norabidea barne."}, "协调后的关联统计表": {"en": "Harmonized association statistics", "fr": "Statistiques d’association harmonisées", "es": "Estadísticas de asociación armonizadas", "eu": "Asoziazio-estatistika bateratuak"}, "变异纳入概率、可信集合与共定位后验": {"en": "Variant inclusion probabilities, credible sets and colocalization posteriors", "fr": "Probabilités d’inclusion, ensembles crédibles et postérieurs de colocalisation", "es": "Probabilidades de inclusión, conjuntos creíbles y posteriores de colocalización", "eu": "Aldaeren inklusio-probabilitateak, multzo sinesgarriak eta kolokalizazioaren ondorengoak"}, "独立培养用于组间推断；菌株保留为分层单位。": {"en": "Independent cultures support group comparisons; strain remains a grouping unit.", "fr": "Les cultures indépendantes fondent les comparaisons ; la souche reste une unité de regroupement.", "es": "Los cultivos independientes sustentan comparaciones; la cepa conserva su nivel de agrupación.", "eu": "Kultura independenteek taldeen konparazioak sostengatzen dituzte; anduia taldekatze-unitatea da."}, "版本化酵母代谢模型": {"en": "Versioned yeast metabolic model", "fr": "Modèle métabolique de levure versionné", "es": "Modelo metabólico de levadura versionado", "eu": "Bertsiodun legamiaren metabolismo-eredua"}, "培养基与代谢交换约束": {"en": "Medium and metabolic exchange constraints", "fr": "Milieu et contraintes des échanges métaboliques", "es": "Medio y restricciones de intercambio metabólico", "eu": "Ingurunea eta truke metabolikoaren murriztapenak"}, "Yeast9发布版本、SBML/COBRA模型、基因—反应映射及目标函数。": {"en": "Yeast9 release, SBML/COBRA model, gene–reaction mappings and objective.", "fr": "Version Yeast9, modèle SBML/COBRA, correspondances gènes–réactions et objectif.", "es": "Versión Yeast9, modelo SBML/COBRA, relaciones gen–reacción y objetivo.", "eu": "Yeast9 bertsioa, SBML/COBRA eredua, gene-erreakzio erlazioak eta helburua."}, "培养记录中的碳氮源、供氧及交换边界；未测边界以独立情景保存。": {"en": "Carbon and nitrogen sources, oxygenation and exchange bounds from culture records; store unmeasured bounds as separate scenarios.", "fr": "Sources de carbone et d’azote, oxygénation et bornes d’échange issues des cultures ; séparer les scénarios non mesurés.", "es": "Fuentes de carbono y nitrógeno, oxigenación y límites de intercambio de los registros; separar escenarios no medidos.", "eu": "Kultura-erregistroetako karbono eta nitrogeno iturriak, oxigenazioa eta truke-mugak; neurtu gabeko mugak aparteko eszenarioetan gorde."}, "状态特异的菌株相似性与群体分层": {"en": "State-specific strain similarity and sample stratification", "fr": "Similarité des souches et stratification selon l’état", "es": "Similitud de cepas y estratificación según el estado", "eu": "Egoeraren araberako anduien antzekotasuna eta estratifikazioa"}, "哪些菌株在相同细胞状态下趋同，哪些差异只在特定状态出现？": {"en": "Which strains converge within the same cell state, and which differences are state specific?", "fr": "Quelles souches convergent dans un même état, et quelles différences dépendent de l’état ?", "es": "¿Qué cepas convergen en un mismo estado y qué diferencias dependen del estado?", "eu": "Zein anduik egiten dute bat zelula-egoera berean, eta zein alde dira egoera-espezifikoak?"}, "用MrVI构建局部样本距离，以培养汇总表达作基线，再将状态特异的菌株分层接回原始计数噪音。": {"en": "Construct local sample distances with MrVI, compare culture-level expression baselines, and connect state-specific strain groups to raw-count noise.", "fr": "Construire les distances locales avec MrVI, comparer les profils par culture et relier les groupes de souches au bruit des comptages bruts.", "es": "Construir distancias locales con MrVI, compararlas con perfiles por cultivo y relacionar los grupos de cepas con el ruido en conteos crudos.", "eu": "Eraiki laginen tokiko distantziak MrVI bidez, alderatu kultura-mailako profilekin eta lotu andui-taldeak zenbaketa gordinen zaratarekin."}, "状态局部的样本距离图": {"en": "State-local sample distance maps", "fr": "Cartes locales des distances entre échantillons", "es": "Mapas locales de distancias entre muestras", "eu": "Laginen tokiko distantzia-mapak"}, "共同状态覆盖与可比较样本清单": {"en": "Shared-state coverage and comparable samples", "fr": "Couverture des états partagés et échantillons comparables", "es": "Cobertura de estados compartidos y muestras comparables", "eu": "Egoera partekatuen estaldura eta lagin konparagarriak"}, "菌株分层对应的噪音候选": {"en": "Noise candidates associated with strain stratification", "fr": "Candidats de bruit associés à la stratification des souches", "es": "Candidatos de ruido asociados a la estratificación de cepas", "eu": "Anduien estratifikazioarekin lotutako zarata-hautagaiak"}, "检查样本与批次设计矩阵的秩，并保留菌株效应。": {"en": "Check the rank of the sample–batch design and retain strain effects.", "fr": "Vérifier le rang du plan échantillon–lot et préserver les effets de souche.", "es": "Verificar el rango del diseño muestra–lote y conservar efectos de cepa.", "eu": "Egiaztatu lagin-lote diseinuaren heina eta mantendu andui-efektuak."}, "按培养重抽样并比较伪bulk距离；检查低覆盖状态对距离的影响。": {"en": "Resample cultures, compare pseudobulk distances and assess low-coverage states.", "fr": "Rééchantillonner les cultures, comparer les distances pseudobulk et examiner les états peu couverts.", "es": "Remuestrear cultivos, comparar distancias pseudobulk y revisar estados poco cubiertos.", "eu": "Berriz lagindu kulturak, alderatu pseudobulk distantziak eta aztertu estaldura txikiko egoerak."}, "sample_key对应独立样本；batch_key只编码已知技术因素。": {"en": "sample_key identifies independent samples; batch_key encodes known technical factors.", "fr": "sample_key identifie les échantillons indépendants ; batch_key code les facteurs techniques connus.", "es": "sample_key identifica muestras independientes; batch_key codifica factores técnicos conocidos.", "eu": "sample_key-k lagin independenteak adierazten ditu; batch_key-k faktore tekniko ezagunak kodetzen ditu."}, "记录状态分组、距离定义、后验抽样和可接受样本规则。": {"en": "Record state grouping, distance definition, posterior sampling and sample admissibility.", "fr": "Consigner groupes d’états, distance, échantillonnage postérieur et admissibilité.", "es": "Registrar grupos de estado, distancia, muestreo posterior y admisibilidad.", "eu": "Erregistratu egoera-taldeak, distantzia, posterior-laginketa eta laginen onargarritasuna."}, "距离描述表达状态下的样本关系；遗传关系另由基因型与亲缘模型检验。": {"en": "Distances describe expression-state relationships; genetic relationships require genotype and kinship analysis.", "fr": "Les distances décrivent les états d’expression ; les relations génétiques se testent avec génotypes et parenté.", "es": "Las distancias describen estados de expresión; las relaciones genéticas requieren genotipos y parentesco.", "eu": "Distantziek adierazpen-egoeren erlazioak deskribatzen dituzte; erlazio genetikoek genotipoak eta ahaidetasun-analisia behar dituzte."}, "3′端位点使用与表达噪音": {"en": "3′-end usage and expression noise", "fr": "Usage des extrémités 3′ et bruit d’expression", "es": "Uso de extremos 3′ y ruido de expresión", "eu": "3′ muturren erabilera eta adierazpen-zarata"}, "同一基因的3′端使用是否随菌株或状态改变，并解释表达分布差异？": {"en": "Does within-gene 3′-end usage vary by strain or state and explain expression-distribution differences?", "fr": "L’usage des extrémités 3′ varie-t-il selon la souche ou l’état et explique-t-il les distributions d’expression ?", "es": "¿Varía el uso de extremos 3′ según cepa o estado y explica diferencias en la distribución de expresión?", "eu": "Aldatzen al da gene barruko 3′ muturren erabilera anduiaren edo egoeraren arabera, eta azaltzen al ditu adierazpen-banaketak?"}, "从匹配协议的BAM建立峰／位点×细胞矩阵，比较基因内使用比例，再检验位点使用与均值条件化噪音的关联。": {"en": "Build peak/site-by-cell matrices from protocol-matched BAM files, compare within-gene usage and relate it to mean-conditioned noise.", "fr": "Construire les matrices pic/site–cellule à partir des BAM adaptés au protocole, comparer les proportions intragéniques et leur lien avec le bruit conditionné par la moyenne.", "es": "Construir matrices pico/sitio por célula desde BAM compatibles, comparar usos intragénicos y relacionarlos con ruido condicionado por la media.", "eu": "Eraiki gailur/gune-zelula matrizeak protokoloari egokitutako BAMetatik, alderatu gene barruko erabilera eta batezbestekoak baldintzatutako zarata."}, "版本化3′峰／位点矩阵": {"en": "Versioned 3′ peak/site matrices", "fr": "Matrices versionnées des pics/sites 3′", "es": "Matrices versionadas de picos/sitios 3′", "eu": "Bertsiodun 3′ gailur/gune matrizeak"}, "基因内位点使用比例与培养层效应": {"en": "Within-gene site usage and culture-level effects", "fr": "Usage intragénique des sites et effets par culture", "es": "Uso intragénico de sitios y efectos por cultivo", "eu": "Gene barruko gune-erabilera eta kultura-mailako efektuak"}, "端点使用与噪音的关联图": {"en": "End-usage associations with noise", "fr": "Associations entre usage des extrémités et bruit", "es": "Asociaciones entre uso de extremos y ruido", "eu": "Mutur-erabileraren eta zarataren arteko loturak"}, "检查相邻基因重叠、链方向、internal priming和独立UMI支持。": {"en": "Check adjacent-gene overlap, strand, internal priming and independent UMI support.", "fr": "Vérifier chevauchements, brin, amorçage interne et UMI indépendants.", "es": "Verificar solapamientos, hebra, cebado interno y UMI independientes.", "eu": "Egiaztatu geneen gainjartzea, katea, barne-amortzea eta UMI independenteak."}, "保留真实培养重复；按基因总UMI匹配位点检出能力。": {"en": "Retain biological culture replicates and match site detectability by total gene UMIs.", "fr": "Conserver les répétitions biologiques et apparier la détectabilité selon les UMI du gène.", "es": "Conservar réplicas biológicas y equiparar detectabilidad según UMI totales del gen.", "eu": "Mantendu kultura-erreplika biologikoak eta parekatu detektagarritasuna genearen UMI guztien arabera."}, "固定统一位点坐标、gene_id与菌株参考对应；补齐3′UTR或终止区域注释。": {"en": "Fix shared site coordinates, gene IDs and strain-reference mappings; supply 3′UTR or termination-region annotation.", "fr": "Fixer coordonnées, identifiants et correspondances de référence ; fournir les annotations 3′UTR ou de terminaison.", "es": "Fijar coordenadas, identificadores y referencias; aportar anotación de 3′UTR o regiones de terminación.", "eu": "Finkatu koordenatuak, gene-identifikatzaileak eta erreferentzia-mapaketak; eman 3′UTR edo amaiera-eskualdeen anotazioa."}, "Sierra计数保留CB/UB；SCAPE按实际文库设置片段分布和位点搜索范围。": {"en": "Retain CB/UB for Sierra counts; set SCAPE fragment distributions and site search regions from the actual library.", "fr": "Conserver CB/UB pour Sierra ; régler distributions de fragments et régions SCAPE selon la bibliothèque.", "es": "Conservar CB/UB para Sierra; ajustar distribuciones y regiones SCAPE a la biblioteca real.", "eu": "Gorde CB/UB Sierra zenbaketarako; egokitu SCAPEren zati-banaketak eta bilaketa-eskualdeak benetako liburutegiari."}, "峰使用、推断切割位点和poly(A)尾长分别记录；本分支估计前两者。": {"en": "Record peak usage, inferred cleavage sites and poly(A)-tail length separately; this branch estimates the first two.", "fr": "Distinguer usage des pics, sites de clivage inférés et longueur poly(A) ; cette branche estime les deux premiers.", "es": "Separar uso de picos, sitios de corte inferidos y longitud de cola poli(A); esta rama estima los dos primeros.", "eu": "Bereizi gailur-erabilera, inferitutako ebaketa-guneak eta poli(A) luzera; adar honek lehen biak estimatzen ditu."}, "代谢反应状态与噪音耦合": {"en": "Metabolic reaction states and noise coupling", "fr": "États des réactions métaboliques et couplage au bruit", "es": "Estados de reacción metabólica y acoplamiento al ruido", "eu": "Erreakzio metabolikoen egoerak eta zaratarekiko akoplamendua"}, "哪些表达噪音差异与酵母代谢网络的可行反应状态共同变化？": {"en": "Which expression-noise differences co-vary with feasible states of the yeast metabolic network?", "fr": "Quelles différences de bruit covarient avec les états réalisables du réseau métabolique de levure ?", "es": "¿Qué diferencias de ruido covarían con estados factibles de la red metabólica de levadura?", "eu": "Zein adierazpen-zarata alderik kobariatzen dute legamiaren sare metabolikoaren egoera egingarriekin?"}, "用Yeast9的基因—反应规则映射表达，构建GIMME条件模型，并以pFBA及可行区间描述反应状态，再与原始计数噪音关联。": {"en": "Map expression through Yeast9 gene–reaction rules, build GIMME context models, summarize reaction states with pFBA and feasible ranges, and relate them to raw-count noise.", "fr": "Mapper l’expression aux règles gène–réaction de Yeast9, construire les modèles GIMME, résumer les états par pFBA et intervalles réalisables, puis les relier au bruit brut.", "es": "Mapear expresión a reglas gen–reacción de Yeast9, construir modelos GIMME, resumir estados mediante pFBA e intervalos factibles y asociarlos al ruido crudo.", "eu": "Mapatu adierazpena Yeast9ren gene-erreakzio arauetara, eraiki GIMME ereduak, laburtu pFBA eta tarte egingarriekin eta lotu zarata gordinarekin."}, "基因—反应映射覆盖": {"en": "Gene–reaction mapping coverage", "fr": "Couverture des correspondances gènes–réactions", "es": "Cobertura de relaciones gen–reacción", "eu": "Gene-erreakzio mapaketaren estaldura"}, "反应状态、可行区间与求解状态": {"en": "Reaction states, feasible ranges and solver status", "fr": "États réactionnels, intervalles réalisables et état du solveur", "es": "Estados de reacción, intervalos factibles y estado del solucionador", "eu": "Erreakzio-egoerak, tarte egingarriak eta ebazlearen egoera"}, "代谢状态相关的噪音候选": {"en": "Metabolic-state-associated noise candidates", "fr": "Candidats de bruit associés à l’état métabolique", "es": "Candidatos de ruido asociados al estado metabólico", "eu": "Egoera metabolikoarekin lotutako zarata-hautagaiak"}, "对照表达通路评分，并检查低检出酶、复合物及同工酶的映射。": {"en": "Compare pathway-expression scores and inspect low-detection enzymes, complexes and isoenzymes.", "fr": "Comparer les scores d’expression et examiner enzymes peu détectées, complexes et isoenzymes.", "es": "Comparar puntuaciones de expresión y revisar enzimas poco detectadas, complejos e isoenzimas.", "eu": "Alderatu adierazpen-puntuazioak eta aztertu gutxi detektatutako entzimak, konplexuak eta isoentzimak."}, "改变表达约束、目标函数和交换边界，记录候选方向及可行性。": {"en": "Vary expression constraints, objectives and exchange bounds; record candidate direction and feasibility.", "fr": "Faire varier contraintes, objectifs et bornes d’échange ; consigner direction et faisabilité.", "es": "Variar restricciones, objetivos y límites de intercambio; registrar dirección y factibilidad.", "eu": "Aldatu adierazpen-murriztapenak, helburuak eta truke-mugak; erregistratu norabidea eta egingarritasuna."}, "固定模型发布版本、基因ID、AND/OR规则和非负表达输入。": {"en": "Fix model release, gene IDs, AND/OR rules and nonnegative expression input.", "fr": "Fixer version, identifiants, règles AND/OR et expression non négative.", "es": "Fijar versión, identificadores, reglas AND/OR y expresión no negativa.", "eu": "Finkatu bertsioa, gene-identifikatzaileak, AND/OR arauak eta adierazpen ez-negatiboa."}, "培养条件来自原始记录；未知交换边界作为情景变量。": {"en": "Use recorded culture conditions; treat unknown exchange bounds as scenario variables.", "fr": "Utiliser les conditions documentées ; traiter les bornes inconnues comme variables de scénario.", "es": "Usar condiciones documentadas; tratar límites desconocidos como variables de escenario.", "eu": "Erabili erregistratutako kultura-baldintzak; hartu truke-muga ezezagunak eszenario-aldagai gisa."}, "输出为表达约束下的预测反应状态；通量单位和尺度由模型边界决定。": {"en": "Outputs are predicted reaction states under expression constraints; flux units and scale follow model bounds.", "fr": "Les sorties sont des états réactionnels prédits ; unités et échelle des flux dépendent des bornes du modèle.", "es": "Los resultados son estados de reacción predichos; unidades y escala de flujo dependen de los límites del modelo.", "eu": "Emaitzak adierazpen-murriztapenetako erreakzio-egoera iragarriak dira; fluxu-unitateak eta eskala ereduaren mugen araberakoak dira."}, "原始计数AnnData与样本／批次标签": {"en": "Raw-count AnnData and sample/batch labels", "fr": "AnnData de comptages bruts et étiquettes échantillon/lot", "es": "AnnData de conteos crudos y etiquetas muestra/lote", "eu": "Zenbaketa gordinen AnnData eta lagin/lote etiketak"}, "样本与技术层级": {"en": "Sample and technical hierarchy", "fr": "Hiérarchie des échantillons et des facteurs techniques", "es": "Jerarquía de muestras y factores técnicos", "eu": "Laginen eta faktore teknikoen hierarkia"}, "输出粒度与后验抽样": {"en": "Output resolution and posterior sampling", "fr": "Résolution des sorties et échantillonnage postérieur", "es": "Resolución de salida y muestreo posterior", "eu": "Irteeraren bereizmena eta posterior-laginketa"}, "排序BAM、GTF、剪接位点与细胞barcode清单": {"en": "Sorted BAM, GTF, splice junctions and cell-barcode list", "fr": "BAM trié, GTF, jonctions et liste des barcodes", "es": "BAM ordenado, GTF, uniones y lista de códigos celulares", "eu": "BAM ordenatua, GTF, loturak eta zelula-barkodeen zerrenda"}, "参考与染色体标识": {"en": "Reference and chromosome identifiers", "fr": "Identifiants de référence et de chromosomes", "es": "Identificadores de referencia y cromosomas", "eu": "Erreferentzia eta kromosoma-identifikatzaileak"}, "分子计数与峰筛选": {"en": "Molecule counting and peak filtering", "fr": "Comptage moléculaire et filtrage des pics", "es": "Conteo molecular y filtrado de picos", "eu": "Molekula-zenbaketa eta gailurren iragazketa"}, "峰代表覆盖区域；差异使用检验按真实培养聚合。": {"en": "Peaks represent coverage regions; aggregate differential-usage tests by actual culture.", "fr": "Les pics représentent des régions couvertes ; agréger les tests par culture réelle.", "es": "Los picos representan regiones cubiertas; agregar pruebas por cultivo real.", "eu": "Gailurrek estaldura-eskualdeak adierazten dituzte; agregatu probak benetako kulturaren arabera."}, "3′切割位点混合模型": {"en": "Mixture modeling of 3′ cleavage sites", "fr": "Modèle de mélange des sites de clivage 3′", "es": "Modelo de mezcla de sitios de corte 3′", "eu": "3′ ebaketa-guneen nahasketa-eredua"}, "带CB/UMI的BAM、3′UTR区域与文库片段信息": {"en": "CB/UMI-tagged BAM, 3′UTR regions and library-fragment information", "fr": "BAM avec CB/UMI, régions 3′UTR et informations sur les fragments", "es": "BAM con CB/UMI, regiones 3′UTR e información de fragmentos", "eu": "CB/UMI etiketadun BAM, 3′UTR eskualdeak eta zati-informazioa"}, "区域和分子标识": {"en": "Regions and molecular identifiers", "fr": "Régions et identifiants moléculaires", "es": "Regiones e identificadores moleculares", "eu": "Eskualdeak eta molekula-identifikatzaileak"}, "片段模型与位点搜索": {"en": "Fragment model and site search", "fr": "Modèle des fragments et recherche de sites", "es": "Modelo de fragmentos y búsqueda de sitios", "eu": "Zati-eredua eta gune-bilaketa"}, "酵母模型、基因表达、培养基及交换约束": {"en": "Yeast model, gene expression, medium and exchange constraints", "fr": "Modèle de levure, expression, milieu et contraintes d’échange", "es": "Modelo de levadura, expresión, medio y restricciones de intercambio", "eu": "Legamiaren eredua, adierazpena, ingurunea eta truke-murriztapenak"}, "模型版本与基因规则": {"en": "Model release and gene rules", "fr": "Version du modèle et règles génétiques", "es": "Versión del modelo y reglas génicas", "eu": "Eredu-bertsioa eta gene-arauak"}, "环境、目标与表达约束": {"en": "Environment, objective and expression constraints", "fr": "Environnement, objectif et contraintes d’expression", "es": "Entorno, objetivo y restricciones de expresión", "eu": "Ingurunea, helburua eta adierazpen-murriztapenak"}, "扰动特异信号与系统偏移基准": {"en": "Perturbation-specific signals versus systematic-shift baselines", "fr": "Signaux spécifiques aux perturbations et références de décalage systématique", "es": "Señales específicas de perturbación y referencias de desplazamiento sistemático", "eu": "Perturbazio-espezifikoko seinaleak eta desplazamendu sistematikoaren oinarriak"}, "真实扰动标签、模型预测与留出集真值": {"en": "Observed perturbation labels, model predictions and held-out outcomes", "fr": "Étiquettes de perturbation, prédictions et observations réservées", "es": "Etiquetas reales, predicciones y resultados reservados", "eu": "Benetako perturbazio-etiketak, iragarpenak eta gordetako emaitzak"}, "匹配均值基线与扰动中心识别结果": {"en": "Matching-mean baseline and perturbation-centroid identification", "fr": "Référence de moyenne appariée et identification des centroïdes", "es": "Referencia de media emparejada e identificación de centroides", "eu": "Batezbesteko parekatuaren oinarria eta zentroideen identifikazioa"}, "按菌株、培养和扰动组合划分数据；训练集确定特征与调参。": {"en": "Split by strain, culture and perturbation combination; select features and tune on training data.", "fr": "Séparer souches, cultures et combinaisons ; sélectionner variables et paramètres sur l’entraînement.", "es": "Separar cepas, cultivos y combinaciones; seleccionar variables y ajustar con entrenamiento.", "eu": "Banatu anduiaren, kulturaren eta konbinazioaren arabera; hautatu ezaugarriak eta parametroak entrenamenduan."}, "用真实扰动数据评价预测；自然菌株差异保留为观察性对照。": {"en": "Evaluate predictions against real perturbations; retain natural-strain differences as observational comparisons.", "fr": "Évaluer sur des perturbations réelles ; conserver les différences naturelles comme comparaisons observationnelles.", "es": "Evaluar con perturbaciones reales; conservar diferencias naturales como comparaciones observacionales.", "eu": "Ebaluatu benetako perturbazioekin; mantendu andui naturalen aldeak behaketa-konparazio gisa."}, "评价划分与参照": {"en": "Evaluation split and reference", "fr": "Partition d’évaluation et référence", "es": "Partición de evaluación y referencia", "eu": "Ebaluazio-banaketa eta erreferentzia"}, "在留出菌株与扰动组合上比较模型、匹配均值和线性基线；联合评价扰动特异位移、中心识别与完整分布。": {"en": "Compare models, matching-mean and linear baselines on held-out strains and perturbation combinations; assess specific shifts, centroid identification and full distributions.", "fr": "Comparer modèles, moyenne appariée et référence linéaire sur les souches et combinaisons réservées ; évaluer décalages spécifiques, centroïdes et distributions.", "es": "Comparar modelos, media emparejada y referencias lineales en cepas y combinaciones reservadas; evaluar desplazamientos específicos, centroides y distribuciones.", "eu": "Alderatu ereduak, batezbesteko parekatua eta oinarri linealak gordetako anduietan eta konbinazioetan; ebaluatu desplazamenduak, zentroideak eta banaketak."}, "同时报告以对照中心和扰动中心为参照的效应，分开评价共同应答与扰动特异信息。": {"en": "Report effects relative to control and perturbed centroids, separating shared responses from perturbation-specific information.", "fr": "Rapporter les effets relatifs aux centroïdes témoins et perturbés, en séparant réponses communes et spécifiques.", "es": "Informar efectos respecto a centroides de control y perturbados, separando respuestas comunes y específicas.", "eu": "Eman kontrol- eta perturbazio-zentroideekiko efektuak, erantzun partekatuak eta informazio espezifikoa bereiziz."}, "分别比较拓扑、沿轨迹的状态占据和基因变化；真实时间序列另用时间约束。": {"en": "Compare topology, state occupancy and gene changes separately; use time constraints only for observed time series.", "fr": "Comparer séparément topologie, occupation et expression ; réserver les contraintes temporelles aux séries mesurées.", "es": "Comparar topología, ocupación y expresión por separado; usar restricciones temporales para series observadas.", "eu": "Alderatu topologia, egoera-okupazioa eta gene-aldaketak bereizita; erabili denbora-murriztapenak behatutako serieetan."}, "冻结参考基因与标签，按完整菌株和研究来源留出测试，分别记录新状态与技术域差异。": {"en": "Freeze reference genes and labels, hold out entire strains and studies, and distinguish novel states from technical domain shifts.", "fr": "Figer gènes et étiquettes de référence, réserver des souches et études entières, et distinguer états nouveaux et effets techniques.", "es": "Fijar genes y etiquetas de referencia, reservar cepas y estudios completos y distinguir estados nuevos de cambios técnicos.", "eu": "Finkatu erreferentzia-geneak eta etiketak, gorde andui eta ikerketa osoak probarako eta bereizi egoera berriak eta aldaketa teknikoak."}, "潜空间距离": {"en": "Latent-space distance", "fr": "Distance latente", "es": "Distancia latente", "eu": "Espazio latenteko distantzia"}, "比例": {"en": "Fraction", "fr": "Proportion", "es": "Proporción", "eu": "Proportzioa"}, "独立UMI计数": {"en": "Independent UMI count", "fr": "Nombre d’UMI indépendants", "es": "Conteo de UMI independientes", "eu": "UMI independenteen kopurua"}, "关联效应及区间": {"en": "Association effect and interval", "fr": "Effet d’association et intervalle", "es": "Efecto de asociación e intervalo", "eu": "Elkartze-efektua eta tartea"}, "不适用；保留各状态细胞数": {"en": "Not applicable; retain cell counts per state", "fr": "Sans objet ; conserver les effectifs par état", "es": "No aplicable; conservar células por estado", "eu": "Ez dagokio; gorde egoera bakoitzeko zelula-kopuruak"}, "状态局部的样本间距离": {"en": "State-local sample distance", "fr": "Distance locale entre échantillons", "es": "Distancia local entre muestras", "eu": "Laginen tokiko distantzia"}, "同一状态下的样本特异表示之间的距离及培养重抽样稳定性。": {"en": "Distances between sample-specific representations of the same state, with culture-resampling stability.", "fr": "Distances entre représentations d’un même état et stabilité par rééchantillonnage des cultures.", "es": "Distancias entre representaciones del mismo estado y estabilidad al remuestrear cultivos.", "eu": "Egoera bereko lagin-adierazpenen distantziak eta kulturak berriz lagintzean duten egonkortasuna."}, "培养／状态": {"en": "Culture / state", "fr": "Culture / état", "es": "Cultivo / estado", "eu": "Kultura / egoera"}, "样本在目标状态的支持覆盖": {"en": "Sample support across target states", "fr": "Couverture des états cibles par échantillon", "es": "Cobertura de estados objetivo por muestra", "eu": "Laginaren euskarria xede-egoeretan"}, "模型判为有分布支持的细胞—样本配对比例，并保留原始支持分数。": {"en": "Fraction of cell–sample pairs with modeled distributional support, retaining the original support scores.", "fr": "Proportion de paires cellule–échantillon soutenues par le modèle, avec leurs scores.", "es": "Proporción de pares célula–muestra con soporte del modelo, conservando puntuaciones.", "eu": "Ereduaren banaketa-euskarria duten zelula-lagin bikoteen proportzioa, jatorrizko puntuazioekin."}, "该状态内实际评价的细胞—样本配对": {"en": "Evaluated cell–sample pairs in the state", "fr": "Paires cellule–échantillon évaluées dans l’état", "es": "Pares célula–muestra evaluados en el estado", "eu": "Egoeran ebaluatutako zelula-lagin bikoteak"}, "3′位点独立分子支持": {"en": "Independent molecular support for 3′ sites", "fr": "Support moléculaire indépendant des sites 3′", "es": "Soporte molecular independiente de sitios 3′", "eu": "3′ guneen euskarri molekular independentea"}, "逐位点记录独立UMI、歧义分配及内部引物候选；峰计数与模型分配量分层保存。": {"en": "Record independent UMIs, ambiguous assignments and internal-priming candidates per site; separate peak counts from modeled assignments.", "fr": "Consigner UMI, affectations ambiguës et amorçage interne ; séparer comptages de pics et affectations modélisées.", "es": "Registrar UMI, asignaciones ambiguas y cebado interno; separar conteos y asignaciones modeladas.", "eu": "Erregistratu UMIak, esleipen anbiguoak eta barne-amortzea; bereizi zenbaketak eta ereduko esleipenak."}, "位点／基因内可归属分子": {"en": "Assignable molecules within the site/gene", "fr": "Molécules assignables au site/gène", "es": "Moléculas asignables al sitio/gen", "eu": "Gune/gene barruan esleitu daitezkeen molekulak"}, "基因内3′位点使用比例": {"en": "Within-gene 3′ site usage", "fr": "Usage intragénique des sites 3′", "es": "Uso intragénico de sitios 3′", "eu": "Gene barruko 3′ gune-erabilera"}, "位点可归属分子占该基因所有可比较位点分子的比例；培养层模型比较组间效应。": {"en": "Assignable site molecules divided by molecules at comparable sites of the same gene; compare effects at culture level.", "fr": "Molécules du site divisées par celles des sites comparables du gène ; comparer les effets par culture.", "es": "Moléculas del sitio divididas por las de sitios comparables del gen; comparar efectos por cultivo.", "eu": "Guneko molekulak zati gene bereko gune konparagarrietako molekulak; alderatu efektuak kultura-mailan."}, "同一基因可比较位点的分子总数": {"en": "Total molecules at comparable sites of the same gene", "fr": "Total des molécules aux sites comparables du gène", "es": "Moléculas totales en sitios comparables del mismo gen", "eu": "Gene bereko gune konparagarrietako molekula guztien kopurua"}, "端点使用与条件化噪音的关联": {"en": "End usage versus conditional noise", "fr": "Usage des extrémités et bruit conditionnel", "es": "Uso de extremos y ruido condicionado", "eu": "Mutur-erabilera eta zarata baldintzatua"}, "比较位点使用与基因噪音性状的培养层关联，控制均值、深度和状态；位点学习与关联评价分开。": {"en": "Relate site usage to gene-noise traits across cultures, adjusting for mean, depth and state; separate site learning from association evaluation.", "fr": "Relier usage et bruit entre cultures en ajustant moyenne, profondeur et état ; séparer apprentissage des sites et évaluation.", "es": "Relacionar uso y ruido entre cultivos ajustando media, profundidad y estado; separar aprendizaje y evaluación.", "eu": "Lotu erabilera eta zarata kulturen artean, batezbestekoa, sakonera eta egoera doituz; bereizi ikaskuntza eta ebaluazioa."}, "具有可比较位点与噪音估计的独立培养": {"en": "Independent cultures with comparable site and noise estimates", "fr": "Cultures indépendantes avec estimations comparables", "es": "Cultivos independientes con estimaciones comparables", "eu": "Gune- eta zarata-estimazio konparagarriak dituzten kultura independenteak"}, "代谢基因—反应覆盖率": {"en": "Metabolic gene–reaction coverage", "fr": "Couverture des gènes–réactions métaboliques", "es": "Cobertura de genes–reacciones metabólicas", "eu": "Gene-erreakzio metabolikoen estaldura"}, "分别统计模型基因的ID匹配、RNA检出与可评价反应比例，并保留AND/OR映射。": {"en": "Report identifier matching, RNA detection and evaluable reaction fractions separately, retaining AND/OR mappings.", "fr": "Rapporter séparément correspondance, détection ARN et réactions évaluables, avec les règles AND/OR.", "es": "Informar por separado correspondencia, detección de ARN y reacciones evaluables, conservando AND/OR.", "eu": "Eman bereizita identifikatzaileen mapaketa, RNA detekzioa eta erreakzio ebaluagarriak, AND/OR arauekin."}, "模型基因数／带基因规则的反应数，分别报告": {"en": "Model genes / reactions with gene rules, reported separately", "fr": "Gènes du modèle / réactions avec règles génétiques, séparément", "es": "Genes del modelo / reacciones con reglas génicas, por separado", "eu": "Ereduko geneak / gene-arauak dituzten erreakzioak, bereizita"}, "代谢反应可行区间": {"en": "Feasible metabolic reaction ranges", "fr": "Intervalles réalisables des réactions métaboliques", "es": "Intervalos factibles de reacción metabólica", "eu": "Erreakzio metabolikoen tarte egingarriak"}, "在给定环境、目标与表达约束下记录预测通量及可行上下界，并保留求解状态。": {"en": "Record predicted fluxes and feasible bounds under stated environment, objective and expression constraints, retaining solver status.", "fr": "Consigner flux prédits et bornes réalisables sous les contraintes déclarées, avec l’état du solveur.", "es": "Registrar flujos predichos y límites factibles bajo restricciones declaradas, con estado del solucionador.", "eu": "Erregistratu fluxu iragarriak eta muga egingarriak adierazitako murriztapenekin, ebazlearen egoerarekin."}, "模型通量单位": {"en": "Model flux units", "fr": "Unités de flux du modèle", "es": "Unidades de flujo del modelo", "eu": "Ereduko fluxu-unitateak"}, "不适用；单位与模型边界一并报告": {"en": "Not applicable; report units with model bounds", "fr": "Sans objet ; rapporter unités et bornes du modèle", "es": "No aplicable; informar unidades y límites del modelo", "eu": "Ez dagokio; eman unitateak ereduaren mugekin"}, "代谢状态—噪音关联的情景稳定性": {"en": "Scenario stability of metabolic-state–noise associations", "fr": "Stabilité des associations métabolisme–bruit selon les scénarios", "es": "Estabilidad de asociaciones metabolismo–ruido entre escenarios", "eu": "Metabolismo-zarata loturen egonkortasuna eszenarioetan"}, "跨表达约束、目标函数和交换边界比较关联方向，并以酵母通路表达评分作对照。": {"en": "Compare association directions across expression constraints, objectives and exchange bounds, using yeast pathway scores as a comparator.", "fr": "Comparer les directions selon contraintes, objectifs et bornes, avec les scores de voies de levure comme référence.", "es": "Comparar direcciones entre restricciones, objetivos y límites, usando puntuaciones de vías de levadura como referencia.", "eu": "Alderatu norabideak murriztapen, helburu eta mugen artean, legamiaren bide-puntuazioak erreferentziatzat erabiliz."}, "预先定义的可行模型情景": {"en": "Prespecified feasible model scenarios", "fr": "Scénarios réalisables prédéfinis", "es": "Escenarios factibles predefinidos", "eu": "Aurrez definitutako eredu-eszenario egingarriak"}, "扰动特异中心识别准确率": {"en": "Perturbation-specific centroid accuracy", "fr": "Exactitude d’identification du centroïde de perturbation", "es": "Exactitud de identificación del centroide de perturbación", "eu": "Perturbazio-zentroidearen identifikazio-zehaztasuna"}, "预测响应更接近其对应真实扰动中心而非其他扰动中心的比例，并与匹配均值基线比较。": {"en": "Fraction of predictions nearest their matching observed perturbation centroid, compared with a matching-mean baseline.", "fr": "Proportion des prédictions les plus proches du centroïde observé correspondant, comparée à la moyenne appariée.", "es": "Proporción de predicciones más próximas al centroide real correspondiente, comparada con la media emparejada.", "eu": "Dagokien benetako zentroidetik hurbilen dauden iragarpenen proportzioa, batezbesteko parekatuarekin alderatuta."}, "留出集内具有真值中心的扰动": {"en": "Held-out perturbations with observed centroids", "fr": "Perturbations réservées avec centroïdes observés", "es": "Perturbaciones reservadas con centroides observados", "eu": "Behatutako zentroideak dituzten gordetako perturbazioak"}, "原文方法与官方入口核对": {"en": "Primary methods and official entry points checked", "fr": "Méthodes originales et accès officiels vérifiés", "es": "Métodos originales y accesos oficiales verificados", "eu": "Jatorrizko metodoak eta sarbide ofizialak egiaztatuta"}, "可迁移的单细胞计算方法": {"en": "Transferable single-cell computational method", "fr": "Méthode unicellulaire transférable", "es": "Método computacional unicelular transferible", "eu": "Zelula bakarreko metodo konputazional transferigarria"}, "方法依据": {"en": "Method evidence", "fr": "Fondement méthodologique", "es": "Evidencia metodológica", "eu": "Metodoaren ebidentzia"}, "方法参考": {"en": "Method reference", "fr": "Référence méthodologique", "es": "Referencia metodológica", "eu": "Metodo-erreferentzia"}, "酿酒酵母": {"en": "Saccharomyces cerevisiae", "fr": "Saccharomyces cerevisiae", "es": "Saccharomyces cerevisiae", "eu": "Saccharomyces cerevisiae"}, "酵母原生": {"en": "Yeast-native", "fr": "Natif de levure", "es": "Nativo de levadura", "eu": "Legamiaren jatorrizkoa"}, "将未匹配基因、未检出RNA和实测表达分开；酶表达不直接换算成反应速率。": {"en": "Separate unmapped genes, undetected RNA and measured expression; enzyme expression is not directly converted to reaction rates.", "fr": "Séparer gènes non appariés, ARN non détecté et expression mesurée ; ne pas convertir directement l’expression en vitesse réactionnelle.", "es": "Separar genes sin correspondencia, ARN no detectado y expresión medida; no convertir expresión directamente en tasas de reacción.", "eu": "Bereizi mapatu gabeko geneak, detektatu gabeko RNA eta neurtutako adierazpena; ez bihurtu adierazpena zuzenean erreakzio-abiadura."}, "明确比较单位、条件、培养重复和待检验效应。": {"en": "Define comparison units, conditions, culture replicates and target effects.", "fr": "Définir unités de comparaison, conditions, répétitions et effets cibles.", "es": "Definir unidades de comparación, condiciones, réplicas y efectos objetivo.", "eu": "Definitu konparazio-unitateak, baldintzak, erreplikak eta xede-efektuak."}, "记录计数层、基因纳入规则、协变量、参考版本和软件版本。": {"en": "Record count layers, gene inclusion, covariates and reference/software versions.", "fr": "Consigner couches de comptage, inclusion des gènes, covariables et versions.", "es": "Registrar capas de conteo, inclusión de genes, covariables y versiones.", "eu": "Erregistratu zenbaketa-geruzak, gene-hautaketa, kobariableak eta bertsioak."}, "预先定义多重检验范围、重抽样层级、随机种子和敏感性分支。": {"en": "Prespecify the testing family, resampling hierarchy, random seed and sensitivity analyses.", "fr": "Prédéfinir famille de tests, hiérarchie de rééchantillonnage, graine et analyses de sensibilité.", "es": "Predefinir familia de pruebas, jerarquía de remuestreo, semilla y análisis de sensibilidad.", "eu": "Aurrez definitu proba-familia, laginketa-hierarkia, hazia eta sentikortasun-analisiak."}, "在有独立参考标签的留出菌株内，随分数规则记录接受细胞比例、接受集标签错误、各状态召回及unknown比例。": {"en": "In held-out strains with independent reference labels, record acceptance, accepted-label error, state recall and unknown fractions across score rules.", "fr": "Dans les souches réservées avec référence indépendante, mesurer acceptation, erreur, rappel par état et fraction inconnue selon les règles de score.", "es": "En cepas reservadas con referencia independiente, registrar aceptación, error, sensibilidad por estado y fracción desconocida según las reglas.", "eu": "Erreferentzia independentea duten gordetako anduietan, erregistratu onarpena, errorea, egoeraren araberako berreskurapena eta ezezagunen proportzioa."}, "在菌株和状态内，检查集合分数与UMI、检出基因数、背景比例及文库的关系，并对照匹配表达量和集合大小的基因集。": {"en": "Within strain and state, relate set scores to UMI depth, detected genes, background and library, using expression- and size-matched sets as controls.", "fr": "Dans chaque souche et état, relier les scores aux UMI, gènes détectés, bruit de fond et bibliothèque, avec des ensembles appariés en expression et taille.", "es": "Dentro de cada cepa y estado, relacionar puntuaciones con UMI, genes detectados, fondo y biblioteca, usando conjuntos equiparados por expresión y tamaño.", "eu": "Andui eta egoera bakoitzean, lotu puntuazioak UMIekin, detektatutako geneekin, hondoarekin eta liburutegiarekin, adierazpenez eta tamainaz parekatutako multzoekin."}, "需适配": {"en": "Adaptation required", "fr": "Adaptation requise", "es": "Requiere adaptación", "eu": "Egokitzapena behar da"}, "扩展分析": {"en": "Extended analysis", "fr": "Analyse complémentaire", "es": "Análisis complementario", "eu": "Analisi osagarria"}, "官方软件入口": {"en": "Official software", "fr": "Logiciel officiel", "es": "Software oficial", "eu": "Software ofiziala"}, "原始方法论文": {"en": "Primary methods paper", "fr": "Article méthodologique original", "es": "Artículo metodológico original", "eu": "Jatorrizko metodo-artikulua"}, "方法": {"en": "Method", "fr": "Méthode", "es": "Método", "eu": "Metodoa"}, "统计单位：保留菌株、培养、文库与细胞的嵌套关系。": {"en": "Statistical units: retain the nesting of strains, cultures, libraries and cells.", "fr": "Unités statistiques : conserver l’emboîtement des souches, cultures, bibliothèques et cellules.", "es": "Unidades estadísticas: conservar la jerarquía de cepas, cultivos, bibliotecas y células.", "eu": "Unitate estatistikoak: gorde anduien, kulturen, liburutegien eta zelulen hierarkia."}, "噪音输入：原始分子计数；状态表征与展示使用独立派生层。": {"en": "Noise inputs: original molecule counts; use separate derived layers for state representation and display.", "fr": "Entrées du bruit : comptages moléculaires originaux ; couches dérivées séparées pour les états et l’affichage.", "es": "Datos de ruido: recuentos moleculares originales; capas derivadas separadas para representar estados y visualizar.", "eu": "Zarata-sarrerak: jatorrizko molekula-zenbaketak; egoerak eta bistaratzea aparteko geruza eratorrietan."}, "模型检验：留出培养、深度匹配、负对照与分层重抽样。": {"en": "Model checks: held-out cultures, depth matching, negative controls and hierarchical resampling.", "fr": "Vérification des modèles : cultures réservées, profondeur appariée, témoins négatifs et rééchantillonnage hiérarchique.", "es": "Comprobación: cultivos reservados, profundidad equiparada, controles negativos y remuestreo jerárquico.", "eu": "Ereduen egiaztapena: gordetako kulturak, sakonera parekatua, kontrol negatiboak eta birlaginketa hierarkikoa."}, "追溯记录：样本身份、参考、计数规则、参数、软件版本与随机种子。": {"en": "Provenance: sample identity, reference, counting rules, parameters, software versions and random seeds.", "fr": "Traçabilité : identité des échantillons, référence, règles de comptage, paramètres, versions et graines aléatoires.", "es": "Trazabilidad: identidad de muestras, referencia, reglas de recuento, parámetros, versiones y semillas aleatorias.", "eu": "Trazabilitatea: laginen identitatea, erreferentzia, zenbaketa-arauak, parametroak, bertsioak eta ausazko haziak."}, "原始论文与官方方法资料": {"en": "Primary studies and official documentation", "fr": "Études originales et documentation officielle", "es": "Estudios originales y documentación oficial", "eu": "Jatorrizko ikerketak eta dokumentazio ofiziala"}, "输出：分子计数与处理流程的质量诊断。": {"en": "Output: quality diagnostics for molecular counts and processing.", "fr": "Sortie : diagnostic de qualité des comptages et du traitement.", "es": "Resultado: diagnóstico de calidad de recuentos y procesamiento.", "eu": "Irteera: zenbaketen eta prozesamenduaren kalitate-diagnostikoa."}, "估计对象：所选细胞状态和测量模型下的表达变异。": {"en": "Estimand: expression variation under the selected cell states and measurement model.", "fr": "Quantité estimée : variation d’expression selon les états et le modèle de mesure choisis.", "es": "Estimando: variación de expresión según los estados y el modelo de medida elegidos.", "eu": "Estimazioa: hautatutako egoeren eta neurketa-ereduaren araberako adierazpen-aldakortasuna."}, "输出：细胞状态坐标、分支概率或剪接动力学方向。时间尺度由实际时间信息校准。": {"en": "Outputs: cell-state coordinates, branch probabilities or splicing-dynamic direction. Calibrate time scales with observed timing.", "fr": "Sorties : coordonnées des états, probabilités de branche ou direction de l’épissage. Calibrer le temps sur les observations.", "es": "Resultados: coordenadas de estado, probabilidades de rama o dirección de empalme. Calibrar la escala temporal con tiempos observados.", "eu": "Irteerak: egoera-koordenatuak, adar-probabilitateak edo splicing-dinamika. Kalibratu denbora-eskala behatutako denborekin."}, "输出：共表达关系、调控候选与模块活动分数。": {"en": "Outputs: coexpression relationships, regulatory candidates and module activity scores.", "fr": "Sorties : relations de coexpression, candidats régulateurs et scores d’activité des modules.", "es": "Resultados: relaciones de coexpresión, candidatos reguladores y actividad de módulos.", "eu": "Irteerak: koespresio-erlazioak, hautagai erregulatzaileak eta modulu-jardueraren puntuazioak."}, "估计对象：指定群体、环境与性状尺度下的遗传方差和关联位点。": {"en": "Estimand: genetic variance and associated loci in the specified population, environment and trait scale.", "fr": "Quantité estimée : variance génétique et loci associés dans la population, l’environnement et l’échelle du caractère définis.", "es": "Estimando: varianza genética y loci asociados en la población, ambiente y escala del rasgo definidos.", "eu": "Estimazioa: zehaztutako populazio, ingurune eta ezaugarri-eskalako bariantza genetikoa eta lotutako lokusak."}, "标签按RNA状态、功能角色和蛋白证据分层；记录参考情境与未分配细胞。": {"en": "Separate RNA-state, functional-role and protein-evidence labels; record reference context and unassigned cells.", "fr": "Séparer les étiquettes d’état ARN, de fonction et de preuve protéique ; conserver contexte et cellules non assignées.", "es": "Separar etiquetas de estado de ARN, función y evidencia proteica; registrar contexto y células sin asignar.", "eu": "Bereizi RNA-egoera, funtzioa eta proteina-ebidentzia; gorde testuingurua eta esleitu gabeko zelulak."}, "输出：模型内扰动排序与反事实表达分布；用真实扰动数据评估预测。": {"en": "Outputs: model-based perturbation rankings and counterfactual expression distributions; evaluate predictions with observed perturbations.", "fr": "Sorties : classement des perturbations et distributions contrefactuelles ; évaluer avec des perturbations observées.", "es": "Resultados: clasificación de perturbaciones y distribuciones contrafactuales; evaluar con perturbaciones observadas.", "eu": "Irteerak: ereduko perturbazio-sailkapenak eta banaketa kontrafaktualak; ebaluatu behatutako perturbazioekin."}, "分子计数与质量控制": {"en": "Molecule counting & quality control", "fr": "Comptage moléculaire et qualité", "es": "Recuento molecular y calidad", "eu": "Molekulen zenbaketa eta kalitatea"}, "信号是否能追溯到正确的细胞、分子与基因？": {"en": "Can each signal be traced to the correct cell, molecule and gene?", "fr": "Chaque signal peut-il être relié à la bonne cellule, molécule et au bon gène ?", "es": "¿Puede cada señal vincularse a la célula, molécula y gen correctos?", "eu": "Seinale bakoitza zelula, molekula eta gene zuzenarekin lotu daiteke?"}, "FASTQ · 建库结构 · 参考与样本信息": {"en": "FASTQ · library structure · reference and sample metadata", "fr": "FASTQ · structure de bibliothèque · référence et métadonnées", "es": "FASTQ · estructura de biblioteca · referencia y metadatos", "eu": "FASTQ · liburutegi-egitura · erreferentzia eta metadatuak"}, "状态注释与群体组成": {"en": "State annotation & composition", "fr": "Annotation des états et composition", "es": "Anotación de estados y composición", "eu": "Egoeren anotazioa eta osaera"}, "菌株差异来自哪些细胞状态及其比例？": {"en": "Which cell states and abundances distinguish strains?", "fr": "Quels états et abondances distinguent les souches ?", "es": "¿Qué estados y abundancias distinguen a las cepas?", "eu": "Zein egoerak eta ugaritasunek bereizten dituzte anduiak?"}, "计数矩阵 · marker证据 · 菌株与培养信息": {"en": "Counts · marker evidence · strain and culture metadata", "fr": "Comptages · marqueurs · métadonnées des souches et cultures", "es": "Recuentos · evidencia de marcadores · cepas y cultivos", "eu": "Zenbaketak · markatzaile-ebidentzia · anduiak eta kulturak"}, "表达分布与噪音估计": {"en": "Expression distributions & noise", "fr": "Distributions et bruit d’expression", "es": "Distribuciones y ruido de expresión", "eu": "Adierazpen-banaketak eta zarata"}, "均值、方差、尾部和潜在表达分布如何变化？": {"en": "How do means, variances, tails and latent distributions change?", "fr": "Comment évoluent moyennes, variances, queues et distributions latentes ?", "es": "¿Cómo cambian medias, varianzas, colas y distribuciones latentes?", "eu": "Nola aldatzen dira batezbestekoak, bariantzak, muturrak eta banaketa latenteak?"}, "原始UMI · 捕获或深度信息 · 独立样本": {"en": "Raw UMIs · capture or depth information · independent samples", "fr": "UMI bruts · capture ou profondeur · échantillons indépendants", "es": "UMI originales · captura o profundidad · muestras independientes", "eu": "UMI gordinak · harrapaketa edo sakonera · lagin independenteak"}, "噪音分解与协同缓冲": {"en": "Noise decomposition & buffering", "fr": "Décomposition du bruit et compensation", "es": "Descomposición del ruido y compensación", "eu": "Zarataren deskonposizioa eta konpentsazioa"}, "变异来自状态混合、共享程序还是基因间补偿？": {"en": "Does variation arise from state mixtures, shared programs or gene compensation?", "fr": "La variation vient-elle de mélanges d’états, de programmes partagés ou de compensations ?", "es": "¿La variación procede de mezclas de estados, programas compartidos o compensación génica?", "eu": "Aldakortasuna egoera-nahasketetatik, partekatutako programetatik edo gene-konpentsaziotik dator?"}, "原始UMI · 状态分数 · 旁系同源与功能关系": {"en": "Raw UMIs · state scores · paralog and functional relationships", "fr": "UMI bruts · scores d’état · relations de paralogie et de fonction", "es": "UMI originales · estados · relaciones de paralogía y función", "eu": "UMI gordinak · egoera-puntuazioak · paralogia eta funtzio-erlazioak"}, "调控、通路与代谢": {"en": "Regulation, pathways & metabolism", "fr": "Régulation, voies et métabolisme", "es": "Regulación, rutas y metabolismo", "eu": "Erregulazioa, bideak eta metabolismoa"}, "哪些调控程序和代谢反应与噪音共同变化？": {"en": "Which regulatory programs and metabolic reactions vary with noise?", "fr": "Quels programmes régulateurs et réactions métaboliques varient avec le bruit ?", "es": "¿Qué programas reguladores y reacciones metabólicas varían con el ruido?", "eu": "Zein programa erregulatzaile eta erreakzio metaboliko aldatzen dira zaratarekin?"}, "表达矩阵 · 酵母调控与通路先验 · 代谢模型按需接入": {"en": "Expression · yeast regulatory and pathway priors · metabolic model where needed", "fr": "Expression · connaissances régulatrices et voies de levure · modèle métabolique si requis", "es": "Expresión · regulación y rutas de levadura · modelo metabólico cuando proceda", "eu": "Adierazpena · legamiaren erregulazio eta bide-ezagutzak · eredu metabolikoa behar denean"}, "周期、轨迹与RNA动力学": {"en": "Cycle, trajectories & RNA dynamics", "fr": "Cycle, trajectoires et dynamique ARN", "es": "Ciclo, trayectorias y dinámica de ARN", "eu": "Zikloa, ibilbideak eta RNA dinamika"}, "表达噪音如何随周期位置、状态转变和衰老程序变化？": {"en": "How does noise vary with cycle position, transitions and aging programs?", "fr": "Comment le bruit varie-t-il avec le cycle, les transitions et les programmes de vieillissement ?", "es": "¿Cómo varía el ruido con el ciclo, las transiciones y el envejecimiento?", "eu": "Nola aldatzen da zarata zikloarekin, trantsizioekin eta zahartze-programekin?"}, "计数与状态 · 剪接层；时间或标记数据用于动力学校准": {"en": "Counts and states · splicing layers; timing or labeling for kinetic calibration", "fr": "Comptages et états · couches d’épissage ; temps ou marquage pour la calibration", "es": "Recuentos y estados · capas de empalme; tiempos o marcaje para calibración", "eu": "Zenbaketak eta egoerak · splicing-geruzak; denbora edo markaketa kalibratzeko"}, "RNA加工与端点使用": {"en": "RNA processing & end usage", "fr": "Maturation ARN et utilisation des extrémités", "es": "Procesamiento de ARN y uso de extremos", "eu": "RNA prozesamendua eta muturren erabilera"}, "剪接与poly(A)位点选择是否改变表达分布？": {"en": "Do splicing and poly(A)-site choices alter expression distributions?", "fr": "L’épissage et le choix des sites poly(A) modifient-ils les distributions ?", "es": "¿El empalme y la selección de sitios poli(A) alteran las distribuciones?", "eu": "Splicing-ak eta poli(A) guneek adierazpen-banaketak aldatzen dituzte?"}, "带CB/UMI的BAM · 链特异注释 · 剪接与3′覆盖证据": {"en": "CB/UMI-tagged BAM · stranded annotation · splice and 3′ coverage evidence", "fr": "BAM avec CB/UMI · annotation orientée · épissage et couverture 3′", "es": "BAM con CB/UMI · anotación orientada · empalme y cobertura 3′", "eu": "CB/UMI etiketadun BAM · kate-anotazioa · splicing eta 3′ estaldura"}, "模拟、扰动与预测检验": {"en": "Simulation, perturbation & prediction", "fr": "Simulation, perturbation et prédiction", "es": "Simulación, perturbación y predicción", "eu": "Simulazioa, perturbazioa eta iragarpena"}, "模型能否恢复已知变化并预测留出菌株或扰动？": {"en": "Can models recover known changes and predict held-out strains or perturbations?", "fr": "Les modèles retrouvent-ils les changements connus et prédisent-ils les souches ou perturbations réservées ?", "es": "¿Los modelos recuperan cambios conocidos y predicen cepas o perturbaciones reservadas?", "eu": "Ereduek aldaketa ezagunak berreskuratu eta gordetako anduiak edo perturbazioak iragar ditzakete?"}, "计数 · 模拟真值或参考数据；扰动预测接入处理与对照": {"en": "Counts · simulation truth or reference data; treatment and controls for perturbation prediction", "fr": "Comptages · vérité simulée ou références ; traitements et témoins pour les prédictions", "es": "Recuentos · verdad simulada o referencias; tratamientos y controles para predecir perturbaciones", "eu": "Zenbaketak · simulazio-egia edo erreferentziak; tratamendua eta kontrolak perturbazioak iragartzeko"}, "遗传方差与调控位点": {"en": "Genetic variance & regulatory loci", "fr": "Variance génétique et loci régulateurs", "es": "Varianza genética y loci reguladores", "eu": "Bariantza genetikoa eta lokus erregulatzaileak"}, "哪些变异影响均值、噪音、状态组成和协同表达？": {"en": "Which variants affect means, noise, state composition and coexpression?", "fr": "Quels variants modifient moyenne, bruit, composition et coexpression ?", "es": "¿Qué variantes afectan a medias, ruido, composición y coexpresión?", "eu": "Zein aldaerek eragiten diete batezbestekoei, zaratari, osaerari eta koespresioari?"}, "样本层性状 · 匹配基因型 · 亲缘与协变量": {"en": "Sample-level traits · matched genotypes · relatedness and covariates", "fr": "Caractères par échantillon · génotypes associés · parenté et covariables", "es": "Rasgos por muestra · genotipos asociados · parentesco y covariables", "eu": "Lagin-mailako ezaugarriak · genotipo parekatuak · ahaidetasuna eta kobariableak"}, "群体历史与表达稳健性": {"en": "Population history & expression robustness", "fr": "Histoire des populations et robustesse", "es": "Historia poblacional y robustez", "eu": "Populazio-historia eta sendotasuna"}, "噪音性状如何沿群体历史变化，并表现出稳健性或可塑性？": {"en": "How do noise traits vary across population history, robustness and plasticity?", "fr": "Comment les caractères de bruit varient-ils avec l’histoire, la robustesse et la plasticité ?", "es": "¿Cómo varían los rasgos de ruido con la historia, robustez y plasticidad?", "eu": "Nola aldatzen dira zarata-ezaugarriak historiarekin, sendotasunarekin eta plastikotasunarekin?"}, "菌株噪音性状 · 系统关系；环境、生态或适合度资料按需接入": {"en": "Strain noise traits · phylogenetic relationships; environment, ecology or fitness as needed", "fr": "Bruit par souche · relations phylogénétiques ; environnement, écologie ou valeur sélective si requis", "es": "Ruido por cepa · relaciones filogenéticas; ambiente, ecología o aptitud cuando proceda", "eu": "Anduien zarata-ezaugarriak · erlazio filogenetikoak; ingurunea, ekologia edo egokitasuna behar denean"}};window.YV_TEXT=Object.assign(window.YV_TEXT||{},text);const content={"projects": {"shared_genetic_architecture": {"en": {"title": "Shared genetic effects, coordinated noise and colocalization", "question": "Does a locus jointly alter means, noise, gene covariance and state occupancy?", "goal": "Does a locus jointly alter means, noise, gene covariance and state occupancy?", "method": "Import association results for means, noise, covariance and state proportions; use mashr for cross-state sharing and original association coefficients, standard errors and matched LD for SuSiE and coloc."}, "fr": {"title": "Effets partagés, bruit coordonné et colocalisation", "question": "Un locus modifie-t-il moyenne, bruit, covariance et occupation des états ?", "goal": "Un locus modifie-t-il moyenne, bruit, covariance et occupation des états ?", "method": "Importer les associations de moyenne, bruit, covariance et proportions ; utiliser mashr pour le partage, puis les coefficients originaux, erreurs-types et LD apparié pour SuSiE et coloc."}, "es": {"title": "Efectos compartidos, ruido coordinado y colocalización", "question": "¿Un locus modifica media, ruido, covarianza y ocupación de estados?", "goal": "¿Un locus modifica media, ruido, covarianza y ocupación de estados?", "method": "Importar asociaciones de media, ruido, covarianza y proporciones; usar mashr para compartir efectos y coeficientes originales, errores estándar y LD emparejado para SuSiE y coloc."}, "eu": {"title": "Efektu partekatuak, zarata koordinatua eta kolokalizazioa", "question": "Lokus batek batera aldatzen al ditu batezbestekoa, zarata, kobariantza eta egoera-okupazioa?", "goal": "Lokus batek batera aldatzen al ditu batezbestekoa, zarata, kobariantza eta egoera-okupazioa?", "method": "Inportatu batezbesteko, zarata, kobariantza eta proportzioen asoziazioak; erabili mashr partekatzea aztertzeko, eta jatorrizko koefizienteak, errore estandarrak eta LD parekatua SuSiE eta coloc-erako."}}, "allelic_noise_context": {"en": {"title": "Allele-specific noise and state regulation", "question": "Do the two alleles within a cell differ in stability and state response?", "goal": "Do the two alleles within a cell differ in stability and state response?", "method": "Build haplotype UMI matrices in heterozygous strains; use scDALI for state-dependent imbalance and compare mean-adjusted allelic noise in the same cells."}, "fr": {"title": "Bruit allélique et régulation selon l’état", "question": "Les deux allèles d’une cellule diffèrent-ils par stabilité et réponse à l’état ?", "goal": "Les deux allèles d’une cellule diffèrent-ils par stabilité et réponse à l’état ?", "method": "Construire les matrices UMI par haplotype ; utiliser scDALI et comparer le bruit allélique ajusté dans les mêmes cellules."}, "es": {"title": "Ruido alélico y regulación por estado", "question": "¿Difieren los dos alelos de una célula en estabilidad y respuesta al estado?", "goal": "¿Difieren los dos alelos de una célula en estabilidad y respuesta al estado?", "method": "Construir matrices UMI por haplotipo; usar scDALI y comparar ruido alélico ajustado en las mismas células."}, "eu": {"title": "Aleloaren araberako zarata eta egoera-erregulazioa", "question": "Zelula bereko bi aleloek egonkortasun eta egoera-erantzun desberdinak al dituzte?", "goal": "Zelula bereko bi aleloek egonkortasun eta egoera-erantzun desberdinak al dituzte?", "method": "Eraiki haplotipoen UMI matrizeak; erabili scDALI eta konparatu aleloen zarata doitua zelula beretan."}}, "rare_regulatory_architecture": {"en": {"title": "Rare regulatory variants and set effects", "question": "Do low-frequency variants jointly alter gene or program stability?", "goal": "Do low-frequency variants jointly alter gene or program stability?", "method": "Group variants by yeast promoters, coding regions or functions; use SAIGE-QTL for mean counts and GMMAT for strain noise, then assess carriers and culture reproducibility."}, "fr": {"title": "Variants régulateurs rares et effets de groupes", "question": "Des variants peu fréquents modifient-ils ensemble la stabilité d’un gène ou programme ?", "goal": "Des variants peu fréquents modifient-ils ensemble la stabilité d’un gène ou programme ?", "method": "Regrouper par promoteurs, régions codantes ou fonctions ; tester moyenne avec SAIGE-QTL et bruit avec GMMAT, puis examiner porteurs et reproductibilité."}, "es": {"title": "Variantes reguladoras raras y efectos de conjuntos", "question": "¿Variantes poco frecuentes alteran conjuntamente la estabilidad de un gen o programa?", "goal": "¿Variantes poco frecuentes alteran conjuntamente la estabilidad de un gen o programa?", "method": "Agrupar por promotores, regiones codificantes o funciones; probar medias con SAIGE-QTL y ruido con GMMAT, revisando portadores y reproducibilidad."}, "eu": {"title": "Aldaera erregulatzaile arraroak eta multzoen efektuak", "question": "Maiztasun txikiko aldaerek batera aldatzen al dute gene edo programa baten egonkortasuna?", "goal": "Maiztasun txikiko aldaerek batera aldatzen al dute gene edo programa baten egonkortasuna?", "method": "Taldekatu sustatzaile, kodetze-eskualde edo funtzioetan; probatu batezbestekoak SAIGE-QTL-rekin eta zarata GMMAT-rekin, eramaileak eta erreproduzigarritasuna aztertuz."}}, "epistatic_noise_architecture": {"en": {"title": "Genetic interactions controlling expression noise", "question": "Does a noise-QTL effect depend on a second locus?", "goal": "Does a noise-QTL effect depend on a second locus?", "method": "Define locus pairs from QTLs and regulatory relationships; compare additive and interaction models with relatedness, then validate predictive gain in held-out strains."}, "fr": {"title": "Interactions génétiques du bruit d’expression", "question": "L’effet d’un QTL de bruit dépend-il d’un second locus ?", "goal": "L’effet d’un QTL de bruit dépend-il d’un second locus ?", "method": "Définir les paires par QTL et régulation ; comparer modèles additif et interactif avec parenté, puis valider sur des souches réservées."}, "es": {"title": "Interacciones genéticas del ruido de expresión", "question": "¿Depende el efecto de un QTL de ruido de otro locus?", "goal": "¿Depende el efecto de un QTL de ruido de otro locus?", "method": "Definir pares desde QTL y regulación; comparar aditividad e interacción con parentesco y validar en cepas reservadas."}, "eu": {"title": "Espresio-zarataren interakzio genetikoak", "question": "Zarata-QTL baten efektua beste lokus baten araberakoa al da?", "goal": "Zarata-QTL baten efektua beste lokus baten araberakoa al da?", "method": "Definitu bikoteak QTL eta erregulaziotik; konparatu eredu gehigarri eta interaktiboa ahaidetasunarekin eta balioztatu gordetako anduietan."}}, "local_sample_landscapes": {"en": {"title": "State-specific strain similarity and sample stratification", "question": "Which strains converge within the same cell state, and which differences are state specific?", "method": "Construct local sample distances with MrVI, compare culture-level expression baselines, and connect state-specific strain groups to raw-count noise."}, "fr": {"title": "Similarité des souches et stratification selon l’état", "question": "Quelles souches convergent dans un même état, et quelles différences dépendent de l’état ?", "method": "Construire les distances locales avec MrVI, comparer les profils par culture et relier les groupes de souches au bruit des comptages bruts."}, "es": {"title": "Similitud de cepas y estratificación según el estado", "question": "¿Qué cepas convergen en un mismo estado y qué diferencias dependen del estado?", "method": "Construir distancias locales con MrVI, compararlas con perfiles por cultivo y relacionar los grupos de cepas con el ruido en conteos crudos."}, "eu": {"title": "Egoeraren araberako anduien antzekotasuna eta estratifikazioa", "question": "Zein anduik egiten dute bat zelula-egoera berean, eta zein alde dira egoera-espezifikoak?", "method": "Eraiki laginen tokiko distantziak MrVI bidez, alderatu kultura-mailako profilekin eta lotu andui-taldeak zenbaketa gordinen zaratarekin."}}, "apa_usage_noise": {"en": {"title": "3′-end usage and expression noise", "question": "Does within-gene 3′-end usage vary by strain or state and explain expression-distribution differences?", "method": "Build peak/site-by-cell matrices from protocol-matched BAM files, compare within-gene usage and relate it to mean-conditioned noise."}, "fr": {"title": "Usage des extrémités 3′ et bruit d’expression", "question": "L’usage des extrémités 3′ varie-t-il selon la souche ou l’état et explique-t-il les distributions d’expression ?", "method": "Construire les matrices pic/site–cellule à partir des BAM adaptés au protocole, comparer les proportions intragéniques et leur lien avec le bruit conditionné par la moyenne."}, "es": {"title": "Uso de extremos 3′ y ruido de expresión", "question": "¿Varía el uso de extremos 3′ según cepa o estado y explica diferencias en la distribución de expresión?", "method": "Construir matrices pico/sitio por célula desde BAM compatibles, comparar usos intragénicos y relacionarlos con ruido condicionado por la media."}, "eu": {"title": "3′ muturren erabilera eta adierazpen-zarata", "question": "Aldatzen al da gene barruko 3′ muturren erabilera anduiaren edo egoeraren arabera, eta azaltzen al ditu adierazpen-banaketak?", "method": "Eraiki gailur/gune-zelula matrizeak protokoloari egokitutako BAMetatik, alderatu gene barruko erabilera eta batezbestekoak baldintzatutako zarata."}}, "metabolic_state_noise": {"en": {"title": "Metabolic reaction states and noise coupling", "question": "Which expression-noise differences co-vary with feasible states of the yeast metabolic network?", "method": "Map expression through Yeast9 gene–reaction rules, build GIMME context models, summarize reaction states with pFBA and feasible ranges, and relate them to raw-count noise."}, "fr": {"title": "États des réactions métaboliques et couplage au bruit", "question": "Quelles différences de bruit covarient avec les états réalisables du réseau métabolique de levure ?", "method": "Mapper l’expression aux règles gène–réaction de Yeast9, construire les modèles GIMME, résumer les états par pFBA et intervalles réalisables, puis les relier au bruit brut."}, "es": {"title": "Estados de reacción metabólica y acoplamiento al ruido", "question": "¿Qué diferencias de ruido covarían con estados factibles de la red metabólica de levadura?", "method": "Mapear expresión a reglas gen–reacción de Yeast9, construir modelos GIMME, resumir estados mediante pFBA e intervalos factibles y asociarlos al ruido crudo."}, "eu": {"title": "Erreakzio metabolikoen egoerak eta zaratarekiko akoplamendua", "question": "Zein adierazpen-zarata alderik kobariatzen dute legamiaren sare metabolikoaren egoera egingarriekin?", "method": "Mapatu adierazpena Yeast9ren gene-erreakzio arauetara, eraiki GIMME ereduak, laburtu pFBA eta tarte egingarriekin eta lotu zarata gordinarekin."}}}, "tools": {"mashr": {"en": {"task": "Joint estimation of genetic effects across states"}, "fr": {"task": "Estimation conjointe des effets génétiques entre états"}, "es": {"task": "Estimación conjunta de efectos genéticos entre estados"}, "eu": {"task": "Egoeren arteko efektu genetikoen estimazio bateratua"}}, "scdali": {"en": {"task": "State-dependent allelic expression imbalance"}, "fr": {"task": "Déséquilibre allélique d’expression dépendant de l’état"}, "es": {"task": "Desequilibrio alélico dependiente del estado"}, "eu": {"task": "Egoeraren araberako alelo-espresioaren desoreka"}}, "saigeqtl": {"en": {"task": "Cell-count eQTL and rare-variant set tests"}, "fr": {"task": "eQTL de comptage et tests de variants rares"}, "es": {"task": "eQTL de recuentos y pruebas de variantes raras"}, "eu": {"task": "Zelula-kontaketaren eQTL eta aldaera arraroen probak"}}, "gmmat": {"en": {"task": "Relatedness-adjusted variant-set association"}, "fr": {"task": "Association de groupes ajustée sur la parenté"}, "es": {"task": "Asociación de conjuntos ajustada por parentesco"}, "eu": {"task": "Ahaidetasunaren arabera doitutako multzoen asoziazioa"}}, "mrvi": {"en": {"task": "State-specific strain similarity and sample stratification"}, "fr": {"task": "Similarité des souches et stratification selon l’état"}, "es": {"task": "Similitud de cepas y estratificación según el estado"}, "eu": {"task": "Egoeraren araberako anduien antzekotasuna eta estratifikazioa"}}, "sierra": {"en": {"task": "Versioned 3′ peak/site matrices"}, "fr": {"task": "Matrices versionnées des pics/sites 3′"}, "es": {"task": "Matrices versionadas de picos/sitios 3′"}, "eu": {"task": "Bertsiodun 3′ gailur/gune matrizeak"}}, "scape": {"en": {"task": "Mixture modeling of 3′ cleavage sites"}, "fr": {"task": "Modèle de mélange des sites de clivage 3′"}, "es": {"task": "Modelo de mezcla de sitios de corte 3′"}, "eu": {"task": "3′ ebaketa-guneen nahasketa-eredua"}}, "yeastgem": {"en": {"task": "Metabolic reaction states and noise coupling"}, "fr": {"task": "États des réactions métaboliques et couplage au bruit"}, "es": {"task": "Estados de reacción metabólica y acoplamiento al ruido"}, "eu": {"task": "Erreakzio metabolikoen egoerak eta zaratarekiko akoplamendua"}}, "systema": {"en": {"task": "Perturbation-specific signals versus systematic-shift baselines"}, "fr": {"task": "Signaux spécifiques aux perturbations et références de décalage systématique"}, "es": {"task": "Señales específicas de perturbación y referencias de desplazamiento sistemático"}, "eu": {"task": "Perturbazio-espezifikoko seinaleak eta desplazamendu sistematikoaren oinarriak"}}}, "metrics": {"genetic_effect_sharing": {"en": {"name": "Genetic-effect sharing across states"}, "fr": {"name": "Partage des effets génétiques entre états"}, "es": {"name": "Efectos genéticos compartidos entre estados"}, "eu": {"name": "Egoeren arteko efektu genetiko partekatuak"}}, "genetic_covariance_qtl": {"en": {"name": "Co-expression and covariance QTLs"}, "fr": {"name": "QTL de coexpression et covariance"}, "es": {"name": "QTL de coexpresión y covarianza"}, "eu": {"name": "Ko-espresio eta kobariantza QTLak"}}, "allelic_molecule_support": {"en": {"name": "Phased-molecule coverage and allelic conflicts"}, "fr": {"name": "Couverture moléculaire phasée et conflits alléliques"}, "es": {"name": "Cobertura molecular faseada y conflictos alélicos"}, "eu": {"name": "Fasekatutako molekulen estaldura eta alelo-gatazkak"}}, "allelic_state_effect": {"en": {"name": "State dependence of allelic imbalance"}, "fr": {"name": "Dépendance du déséquilibre allélique à l’état"}, "es": {"name": "Dependencia del desequilibrio alélico del estado"}, "eu": {"name": "Alelo-desorekaren egoera-mendekotasuna"}}, "allelic_noise_contrast": {"en": {"name": "Paired allelic-noise contrast"}, "fr": {"name": "Contraste du bruit allélique apparié"}, "es": {"name": "Contraste de ruido alélico pareado"}, "eu": {"name": "Alelo parekatuen zarata-kontrastea"}}, "variant_set_support": {"en": {"name": "Variant-set support and association"}, "fr": {"name": "Support et association des groupes de variants"}, "es": {"name": "Soporte y asociación de conjuntos de variantes"}, "eu": {"name": "Aldaera multzoen euskarria eta asoziazioa"}}, "epistatic_noise_effect": {"en": {"name": "Noise epistasis and genotype-combination support"}, "fr": {"name": "Épistasie du bruit et support génotypique"}, "es": {"name": "Epistasis del ruido y soporte genotípico"}, "eu": {"name": "Zarataren epistasia eta genotipo-euskarria"}}, "noise_genetic_partition": {"en": {"name": "Genetic variance partitioning and culture repeatability"}, "fr": {"name": "Partition de variance génétique et répétabilité"}, "es": {"name": "Partición de varianza genética y repetibilidad"}, "eu": {"name": "Bariantza genetikoaren partizioa eta errepikakortasuna"}}, "noise_reaction_norm": {"en": {"name": "Noise reaction norms and environmental stability"}, "fr": {"name": "Normes de réaction du bruit et stabilité environnementale"}, "es": {"name": "Normas de reacción del ruido y estabilidad ambiental"}, "eu": {"name": "Zarataren erreakzio-arauak eta ingurumen-egonkortasuna"}}, "sample_local_distances": {"en": {"name": "State-local sample distance", "definition": "Distances between sample-specific representations of the same state, with culture-resampling stability."}, "fr": {"name": "Distance locale entre échantillons", "definition": "Distances entre représentations d’un même état et stabilité par rééchantillonnage des cultures."}, "es": {"name": "Distancia local entre muestras", "definition": "Distancias entre representaciones del mismo estado y estabilidad al remuestrear cultivos."}, "eu": {"name": "Laginen tokiko distantzia", "definition": "Egoera bereko lagin-adierazpenen distantziak eta kulturak berriz lagintzean duten egonkortasuna."}}, "sample_state_admissibility": {"en": {"name": "Sample support across target states", "definition": "Fraction of cell–sample pairs with modeled distributional support, retaining the original support scores."}, "fr": {"name": "Couverture des états cibles par échantillon", "definition": "Proportion de paires cellule–échantillon soutenues par le modèle, avec leurs scores."}, "es": {"name": "Cobertura de estados objetivo por muestra", "definition": "Proporción de pares célula–muestra con soporte del modelo, conservando puntuaciones."}, "eu": {"name": "Laginaren euskarria xede-egoeretan", "definition": "Ereduaren banaketa-euskarria duten zelula-lagin bikoteen proportzioa, jatorrizko puntuazioekin."}}, "apa_site_molecular_support": {"en": {"name": "Independent molecular support for 3′ sites", "definition": "Record independent UMIs, ambiguous assignments and internal-priming candidates per site; separate peak counts from modeled assignments."}, "fr": {"name": "Support moléculaire indépendant des sites 3′", "definition": "Consigner UMI, affectations ambiguës et amorçage interne ; séparer comptages de pics et affectations modélisées."}, "es": {"name": "Soporte molecular independiente de sitios 3′", "definition": "Registrar UMI, asignaciones ambiguas y cebado interno; separar conteos y asignaciones modeladas."}, "eu": {"name": "3′ guneen euskarri molekular independentea", "definition": "Erregistratu UMIak, esleipen anbiguoak eta barne-amortzea; bereizi zenbaketak eta ereduko esleipenak."}}, "apa_within_gene_usage": {"en": {"name": "Within-gene 3′ site usage", "definition": "Assignable site molecules divided by molecules at comparable sites of the same gene; compare effects at culture level."}, "fr": {"name": "Usage intragénique des sites 3′", "definition": "Molécules du site divisées par celles des sites comparables du gène ; comparer les effets par culture."}, "es": {"name": "Uso intragénico de sitios 3′", "definition": "Moléculas del sitio divididas por las de sitios comparables del gen; comparar efectos por cultivo."}, "eu": {"name": "Gene barruko 3′ gune-erabilera", "definition": "Guneko molekulak zati gene bereko gune konparagarrietako molekulak; alderatu efektuak kultura-mailan."}}, "apa_noise_association": {"en": {"name": "End usage versus conditional noise", "definition": "Relate site usage to gene-noise traits across cultures, adjusting for mean, depth and state; separate site learning from association evaluation."}, "fr": {"name": "Usage des extrémités et bruit conditionnel", "definition": "Relier usage et bruit entre cultures en ajustant moyenne, profondeur et état ; séparer apprentissage des sites et évaluation."}, "es": {"name": "Uso de extremos y ruido condicionado", "definition": "Relacionar uso y ruido entre cultivos ajustando media, profundidad y estado; separar aprendizaje y evaluación."}, "eu": {"name": "Mutur-erabilera eta zarata baldintzatua", "definition": "Lotu erabilera eta zarata kulturen artean, batezbestekoa, sakonera eta egoera doituz; bereizi ikaskuntza eta ebaluazioa."}}, "metabolic_gene_reaction_coverage": {"en": {"name": "Metabolic gene–reaction coverage", "definition": "Report identifier matching, RNA detection and evaluable reaction fractions separately, retaining AND/OR mappings."}, "fr": {"name": "Couverture des gènes–réactions métaboliques", "definition": "Rapporter séparément correspondance, détection ARN et réactions évaluables, avec les règles AND/OR."}, "es": {"name": "Cobertura de genes–reacciones metabólicas", "definition": "Informar por separado correspondencia, detección de ARN y reacciones evaluables, conservando AND/OR."}, "eu": {"name": "Gene-erreakzio metabolikoen estaldura", "definition": "Eman bereizita identifikatzaileen mapaketa, RNA detekzioa eta erreakzio ebaluagarriak, AND/OR arauekin."}}, "metabolic_feasible_ranges": {"en": {"name": "Feasible metabolic reaction ranges", "definition": "Record predicted fluxes and feasible bounds under stated environment, objective and expression constraints, retaining solver status."}, "fr": {"name": "Intervalles réalisables des réactions métaboliques", "definition": "Consigner flux prédits et bornes réalisables sous les contraintes déclarées, avec l’état du solveur."}, "es": {"name": "Intervalos factibles de reacción metabólica", "definition": "Registrar flujos predichos y límites factibles bajo restricciones declaradas, con estado del solucionador."}, "eu": {"name": "Erreakzio metabolikoen tarte egingarriak", "definition": "Erregistratu fluxu iragarriak eta muga egingarriak adierazitako murriztapenekin, ebazlearen egoerarekin."}}, "metabolic_noise_sensitivity": {"en": {"name": "Scenario stability of metabolic-state–noise associations", "definition": "Compare association directions across expression constraints, objectives and exchange bounds, using yeast pathway scores as a comparator."}, "fr": {"name": "Stabilité des associations métabolisme–bruit selon les scénarios", "definition": "Comparer les directions selon contraintes, objectifs et bornes, avec les scores de voies de levure comme référence."}, "es": {"name": "Estabilidad de asociaciones metabolismo–ruido entre escenarios", "definition": "Comparar direcciones entre restricciones, objetivos y límites, usando puntuaciones de vías de levadura como referencia."}, "eu": {"name": "Metabolismo-zarata loturen egonkortasuna eszenarioetan", "definition": "Alderatu norabideak murriztapen, helburu eta mugen artean, legamiaren bide-puntuazioak erreferentziatzat erabiliz."}}, "perturbation_centroid_accuracy": {"en": {"name": "Perturbation-specific centroid accuracy", "definition": "Fraction of predictions nearest their matching observed perturbation centroid, compared with a matching-mean baseline."}, "fr": {"name": "Exactitude d’identification du centroïde de perturbation", "definition": "Proportion des prédictions les plus proches du centroïde observé correspondant, comparée à la moyenne appariée."}, "es": {"name": "Exactitud de identificación del centroide de perturbación", "definition": "Proporción de predicciones más próximas al centroide real correspondiente, comparada con la media emparejada."}, "eu": {"name": "Perturbazio-zentroidearen identifikazio-zehaztasuna", "definition": "Dagokien benetako zentroidetik hurbilen dauden iragarpenen proportzioa, batezbesteko parekatuarekin alderatuta."}}}, "formulas": {}};window.YV_CONTENT=window.YV_CONTENT||{};for(const [type,rows]of Object.entries(content)){window.YV_CONTENT[type]=window.YV_CONTENT[type]||{};for(const [id,langs]of Object.entries(rows)){window.YV_CONTENT[type][id]=Object.assign(window.YV_CONTENT[type][id]||{},langs);}}})();
